pub const TOOL_RUN_REASON_REBASING: u16 = 0xFF00;
/// ⚔️ Framework step: `{0}` provisional changes conflict with the current artifact.
pub const TOOL_RUN_REASON_CONFLICT: u16 = 0xFF01;
