    }
    /// 📍️ Returns the exact emitted physical byte position.
    pub fn position(&self)->u64{self.bytes.len()as u64}
    fn append(&mut self,bytes:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),PackError>{let end=(self.bytes.len()as u64).checked_add(bytes.len()as u64).filter(|end|*end<=self.maximum_file).ok_or(PackError::LimitExceeded("Pack output exceeds max_file_len"))?;let _=end;control.append_bytes(&mut self.bytes,bytes).map_err(PackError::Schema)}
