        let owned=match self.codec.0{0=>None,1=>Some(crate::codec::deflate_compress_controlled(payload,control)?),other=>return Err(PackError::UnsupportedCodec(other))};let stored=owned.as_deref().unwrap_or(payload);if stored.len()as u64>self.maximum_segment{return Err(PackError::LimitExceeded("Pack stored segment exceeds max_segment_len"))}let mut prefix=Prefix::new();prefix.bytes(&[kind,if owned.is_some(){1|(self.codec.0<<1)}else{0}])?;prefix.varint(stored.len()as u64)?;if owned.is_some(){prefix.varint(payload.len()as u64)?;}let mut crc=crate::codec::Crc32cCursor::new();Self::crc(&mut crc,prefix.slice(),control)?;Self::crc(&mut crc,stored,control)?;self.append(prefix.slice(),control)?;self.append(stored,control)?;self.append(&crc.finish().to_le_bytes(),control)?;if kind==KIND_DOCUMENT{Self::hash(&mut self.document_hash,payload,control)?;}Ok(())
    }
    /// 🧱️ Emits an intrinsic raw chunk and admits its physical index entry before publishing it.
    pub fn chunk(&mut self,payload:&[u8],control:&mut NativeEncodeControl<'_>)->Result<ChunkId,PackError>{
