//! 📦️ `pack_io` — native file I/O for the `pack` binary document container family:
//! `FilePackSource`/`FilePackSink` implementing `pack_core`'s `PackSource`/`PackSink` traits over
//! `std::fs::File`, `write_atomic` (temp-file + fsync + rename, no partial file ever visible),
//! `StreamingPackWriter` (an incremental `crate::format::PackWriter<FilePackSink>` that flushes
//! segments to disk as produced rather than buffering the whole file in memory), and
//! `recover_file` (opens a file and forward-scans it via `crate::format::recover`).
//!
//! Everything here is native-only (`std::fs`, `std::sync::Mutex`) and gated behind
//! `#[cfg(not(target_arch = "wasm32"))]` so the crate still compiles — as an effectively-empty
//! crate — for a `wasm32-unknown-unknown` target check. See the `## pack_io` section of the
//! wave-0 contract at `.🧬semio/🦑️repo/🎫️tickets/26/07/27/PACK-BINARY-DOCUMENT-LAYER-ACROSS-ALL-APPS/contract.md`.

#[cfg(not(target_arch = "wasm32"))]
mod native {
    use std::io::Write;
    use std::path::Path;
    use std::sync::atomic::{AtomicU64, Ordering};
    use std::sync::Mutex;

    use crate::format::{Manifest, PackWriter, RecoveryReport, WriteOptions};
    use crate::{PackError, PackLimits, PackSink, PackSource};

    /// 🚨️ Wraps a `std::io::Error` into the crate-wide `PackError::Io` variant — the only
    /// place `std::io::Error` is allowed to appear, per the contract's no-`std::io::Error`-in-
    /// public-signatures rule.
    #[allow(clippy::needless_pass_by_value)] // used as a `map_err` callback, which passes the error by value
    fn io_err(err: std::io::Error) -> PackError {
        PackError::Io(err.to_string())
    }

    //#region 🔖️File
    /// 📂️ A read-only, random-access file source. Positional reads go through
    /// `std::os::unix::fs::FileExt::read_at`/`std::os::windows::fs::FileExt::seek_read` (both
    /// take `&self`, no locking needed) on unix/windows, and a `Mutex`-guarded seek+read fallback
    /// on any other native target — kept behind one `Mutex<File>` field for a single code path.
    pub struct FilePackSource {
        file: Mutex<std::fs::File>,
        len: u64,
    }

    impl FilePackSource {
        /// 📖️ Opens `path` for reading and stat's its length up front.
        pub fn open(path: &Path) -> Result<Self, PackError> {
            let file = std::fs::File::open(path).map_err(io_err)?;
            let len = file.metadata().map_err(io_err)?.len();
            Ok(Self { file: Mutex::new(file), len })
        }
    }

    // 🧮️ `PackSource`/`PackSink` (owned by `semio-framework-replication`, not this packet) are
    // already plain-AFIT `async` traits — see `📓️terra-pack-finish-report.md`
    // §"pure-computation-made-async: the recipe". These impls do genuinely-blocking `std::fs`
    // I/O in an `async fn` body (no `.await` inside): that mirrors the crate's existing idiom of
    // spawning a dedicated thread for blocking work rather than pretending file I/O suspends.
    impl PackSource for FilePackSource {
        async fn len(&self) -> u64 {
            self.len
        }

        async fn read_at(&self, offset: u64, buf: &mut [u8]) -> Result<usize, PackError> {
            if offset > self.len {
                return Err(PackError::Truncated(offset));
            }
            let guard = self.file.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            #[cfg(unix)]
            {
                use std::os::unix::fs::FileExt;
                guard.read_at(buf, offset).map_err(io_err)
            }
            #[cfg(windows)]
            {
                use std::os::windows::fs::FileExt;
                guard.seek_read(buf, offset).map_err(io_err)
            }
            #[cfg(not(any(unix, windows)))]
            {
                use std::io::{Read, Seek, SeekFrom};
                let mut guard = guard;
                guard.seek(SeekFrom::Start(offset)).map_err(io_err)?;
                guard.read(buf).map_err(io_err)
            }
        }
    }

    /// 📤️ A write-only file sink opened truncate-on-create; tracks its own write position
    /// since `std::fs::File` exposes none without a `&mut self` seek.
    pub struct FilePackSink {
        file: std::fs::File,
        position: u64,
    }

    impl FilePackSink {
        /// 🆕️ Creates (truncating any existing file) `path` for writing.
        pub fn create(path: &Path) -> Result<Self, PackError> {
            let file = std::fs::OpenOptions::new().write(true).create(true).truncate(true).open(path).map_err(io_err)?;
            Ok(Self { file, position: 0 })
        }
    }

    impl PackSink for FilePackSink {
        async fn write_all(&mut self, bytes: &[u8]) -> Result<(), PackError> {
            self.file.write_all(bytes).map_err(io_err)?;
            self.position += bytes.len() as u64;
            Ok(())
        }

        async fn position(&self) -> u64 {
            self.position
        }

        async fn flush(&mut self) -> Result<(), PackError> {
            self.file.flush().map_err(io_err)?;
            self.file.sync_all().map_err(io_err)
        }
    }
    //#endregion 🔖️File

    //#region 🔖️Atomic
    /// 🔢️ Per-process monotonic counter mixed into temp-file names so concurrent
    /// `write_atomic` calls (even to the same `path`, even on the same PID) never collide.
    static TMP_COUNTER: AtomicU64 = AtomicU64::new(0);

    /// 🛟️ Writes `bytes` to `path` atomically: writes to a sibling temp file, `fsync`s it,
    /// then `rename`s it into place. `rename` is atomic on every platform this targets, so a
    /// reader can never observe a partially-written `path` — it sees either the old content or
    /// the fully-written new content, never a torn write.
    pub fn write_atomic(path: &Path, bytes: &[u8]) -> Result<(), PackError> {
        let file_name = path.file_name().ok_or_else(|| PackError::Io("write_atomic: path has no file name".to_string()))?;
        let pid = std::process::id();
        let counter = TMP_COUNTER.fetch_add(1, Ordering::Relaxed);
        let tmp_name = format!("{}.tmp-{pid}-{counter}", file_name.to_string_lossy());
        let tmp_path = path.with_file_name(tmp_name);
        {
            let mut tmp_file = std::fs::File::create(&tmp_path).map_err(io_err)?;
            tmp_file.write_all(bytes).map_err(io_err)?;
            tmp_file.sync_all().map_err(io_err)?;
        }
        std::fs::rename(&tmp_path, path).map_err(io_err)?;
        Ok(())
    }
    //#endregion 🔖️Atomic

    //#region 🔖️Stream
    /// 🌊️ An incremental pack file writer: segments/chunks are framed and flushed straight
    /// to disk as they're written rather than buffered in memory for the whole file, wrapping
    /// `crate::format::PackWriter<FilePackSink>`.
    pub struct StreamingPackWriter {
        inner: PackWriter<FilePackSink>,
    }

    impl StreamingPackWriter {
        /// 🚀️ Creates `path` and writes the 32-byte header.
        pub async fn create(path: &Path, options: &WriteOptions) -> Result<Self, PackError> {
            let sink = FilePackSink::create(path)?;
            let inner = PackWriter::begin(sink, options).await?;
            Ok(Self { inner })
        }

        /// 🖇️ Frames, compresses, CRCs, and flushes one segment to disk.
        pub async fn write_segment(&mut self, kind: u8, payload: &[u8]) -> Result<(), PackError> {
            self.inner.write_segment(kind, payload).await
        }

        pub async fn begin_identity_chunk(&mut self, payload_len: usize) -> Result<crate::format::PackIdentityChunk<'_, FilePackSink>, PackError> {
            self.inner.begin_identity_chunk(payload_len).await
        }

        /// 🏁️ Writes the chunk table, manifest, end marker, and footer, `fsync`s (via
        /// `FilePackSink::flush`, called internally by `PackWriter::finish`), and closes the file.
        pub async fn finish(self, manifest: &Manifest) -> Result<(), PackError> {
            self.inner.finish(manifest).await?;
            Ok(())
        }
    }
    //#endregion 🔖️Stream

    //#region 🔖️Recover
    /// 🩺️ Opens `path` and forward-scans it via `crate::format::recover` — for use when a
    /// file's footer fails to parse/validate and the caller wants to salvage whatever valid
    /// segments precede the corruption.
    pub async fn recover_file(path: &Path, limits: &PackLimits) -> Result<RecoveryReport, PackError> {
        let source = FilePackSource::open(path)?;
        crate::format::recover(&source, limits).await
    }
    //#endregion 🔖️Recover

    //#region 🧪️Tests
    #[cfg(test)]
    include!("🧪️tests/🔬️native-unit/🦀️.rs");
    //#endregion 🧪️Tests
}

#[cfg(not(target_arch = "wasm32"))]
pub use native::*;

mod tests {
    use super::*;
    use crate::format::VerificationLevel;
    use crate::{ByteRange, CodecId, KIND_DOCUMENT, KIND_SCHEMA};

    /// 🎲️ Per-test unique scratch directory under `std::env::temp_dir()` — no external
    /// `tempfile` crate dependency, per the contract's std-only preference.
    static DIR_COUNTER: AtomicU64 = AtomicU64::new(0);

    fn scratch_dir(name: &str) -> std::path::PathBuf {
        let pid = std::process::id();
        let counter = DIR_COUNTER.fetch_add(1, Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!("pack_io_test_{name}_{pid}_{counter}"));
        std::fs::create_dir_all(&dir).expect("create scratch dir");
        dir
    }

    //#region 🔖️File
    #[semio_framework_async_macros::async_test]
    async fn file_source_sink_write_then_read_back() {
        let dir = scratch_dir("file_rw");
        let path = dir.join("blob.bin");
        let payload = b"hello pack_io world, this is a test payload";

        let mut sink = FilePackSink::create(&path).unwrap();
        assert_eq!(sink.position().await, 0);
        sink.write_all(&payload[..10]).await.unwrap();
        assert_eq!(sink.position().await, 10);
        sink.write_all(&payload[10..]).await.unwrap();
        assert_eq!(sink.position().await, payload.len() as u64);
        sink.flush().await.unwrap();
        drop(sink);

        let source = FilePackSource::open(&path).unwrap();
        assert_eq!(PackSource::len(&source).await, payload.len() as u64);
        assert!(!source.is_empty().await);

        let mut buf = vec![0u8; payload.len()];
        let n = source.read_at(0, &mut buf).await.unwrap();
        assert_eq!(n, payload.len());
        assert_eq!(&buf, payload);

        let mut mid = [0u8; 5];
        let n = source.read_at(6, &mut mid).await.unwrap();
        assert_eq!(n, 5);
        assert_eq!(&mid, &payload[6..11]);

        let mut exact = vec![0u8; payload.len()];
        source.read_exact_at(0, &mut exact).await.unwrap();
        assert_eq!(exact, payload);

        let mut past_end = [0u8; 4];
        let result = source.read_at(1_000_000, &mut past_end).await;
        assert!(matches!(result, Err(PackError::Truncated(1_000_000))));

        let mut short = [0u8; 100];
        let n = source.read_at((payload.len() - 3) as u64, &mut short).await.unwrap();
        assert_eq!(n, 3);
        assert_eq!(&short[..3], &payload[payload.len() - 3..]);
    }
    //#endregion 🔖️File

    //#region 🔖️Atomic
    #[test]
    fn write_atomic_produces_full_content_and_no_stray_tmp_file() {
        let dir = scratch_dir("atomic_ok");
        let path = dir.join("doc.spk");
        let bytes = b"atomic write payload";

        write_atomic(&path, bytes).unwrap();

        let read_back = std::fs::read(&path).unwrap();
        assert_eq!(read_back, bytes);

        let leftover_tmp = std::fs::read_dir(&dir).unwrap().filter_map(|entry| entry.ok()).any(|entry| entry.file_name().to_string_lossy().contains(".tmp-"));
        assert!(!leftover_tmp, "no .tmp- file should remain after a successful write_atomic");
    }

    #[test]
    fn write_atomic_never_exposes_a_partial_target_from_a_simulated_interrupted_write() {
        let dir = scratch_dir("atomic_interrupt");
        let path = dir.join("doc.spk");
        let original = b"original committed content";

        write_atomic(&path, original).unwrap();

        // Simulate a crash between "temp file written" and "rename into place": create a
        // stray tmp file with the naming scheme write_atomic uses, but never rename it.
        let stray_tmp = path.with_file_name("doc.spk.tmp-999999-0");
        std::fs::write(&stray_tmp, b"garbage-from-a-simulated-crashed-write").unwrap();

        // The target must still show only the original, fully-committed content — the stray
        // (simulated-interrupted) tmp file is never visible at `path`.
        let read_back = std::fs::read(&path).unwrap();
        assert_eq!(read_back, original);

        // A second, real write_atomic call still succeeds and atomically replaces the content
        // even with an unrelated stray tmp file sitting in the same directory.
        let updated = b"second committed content, replaces the first";
        write_atomic(&path, updated).unwrap();
        let read_back = std::fs::read(&path).unwrap();
        assert_eq!(read_back, updated);
    }
    //#endregion 🔖️Atomic

    //#region 🔖️Stream
    /// 📏️ Wire length of a non-compressed segment frame (`kind, flags, seg_len varint,
    /// payload, crc32`) — mirrors `pack_format`'s private `encode_segment` for `CodecId(0)`,
    /// used here only to compute a valid `doc_span.len` for a hand-built `Manifest`.
    async fn uncompressed_segment_wire_len(payload_len: usize) -> u64 {
        let mut len_bytes = Vec::new();
        crate::write_varint_u64(&mut len_bytes, payload_len as u64);
        (1 + 1 + len_bytes.len() + payload_len + 4) as u64
    }

    fn no_compression_options() -> WriteOptions {
        WriteOptions { required_flags: 0, optional_flags: crate::format::OPTIONAL_STREAMED, codec: CodecId(0) }
    }

    #[semio_framework_async_macros::async_test]
    async fn streaming_writer_full_session_multiple_segments_and_a_chunk_round_trips() {
        let dir = scratch_dir("stream_session");
        let path = dir.join("session.spk");
        let doc_payload = b"the streamed document body";
        let chunk_payload = b"a chunk of blob bytes carried alongside the document";
        let schema_payload = b"an extra schema segment written after the chunk";

        let mut writer = StreamingPackWriter::create(&path, &no_compression_options()).await.unwrap();
        writer.write_segment(KIND_DOCUMENT, doc_payload).await.unwrap();
        let mut chunk = writer.begin_identity_chunk(chunk_payload.len()).await.unwrap();
        for fragment in chunk_payload.chunks(7) {
            chunk.write_fragment(fragment).await.unwrap();
        }
        let chunk_id = chunk.finish().await.unwrap();
        writer.write_segment(KIND_SCHEMA, schema_payload).await.unwrap();

        let manifest = Manifest {
            schema_name: String::new(),
            schema_hash: [0u8; 32],
            doc_span: ByteRange { offset: crate::format::HEADER_SIZE as u64, len: uncompressed_segment_wire_len(doc_payload.len()).await },
            doc_frame_count: 1,
            symbols_span: ByteRange { offset: 0, len: 0 },
            chunk_table_span: ByteRange { offset: 0, len: 0 },
            field_index_span: ByteRange { offset: 0, len: 0 },
            uncompressed_body_len: doc_payload.len() as u64,
            field_count: 0,
            chunk_count: 0,
            symbol_count: 0,
        };
        writer.finish(&manifest).await.unwrap();

        let source = FilePackSource::open(&path).unwrap();
        let limits = PackLimits::default();
        let pack_file = crate::format::PackFile::open_manifest(source, &limits, VerificationLevel::Standard).await.unwrap();

        let loaded_manifest = pack_file.manifest().unwrap();
        assert_eq!(loaded_manifest.doc_frame_count, 1);
        assert_eq!(loaded_manifest.uncompressed_body_len, doc_payload.len() as u64);
        assert_eq!(pack_file.chunk_count(), 1);

        let read_chunk = pack_file.read_chunk(chunk_id, VerificationLevel::Full).await.unwrap();
        assert_eq!(read_chunk, chunk_payload);

        // `Full` verification also cross-checks the concatenated document body against the
        // footer's blake3 content hash, proving StreamingPackWriter's running hash matches.
        let body = pack_file.body_bytes(VerificationLevel::Full).await.unwrap();
        assert_eq!(body, doc_payload);

        // Forward-scan recovery should independently see every segment this session wrote:
        // document, chunk, schema, chunk table, manifest, end.
        let report = recover_file(&path, &limits).await.unwrap();
        assert_eq!(report.segments_recovered, 6);
        assert!(report.manifest.is_some());
    }
    //#endregion 🔖️Stream

    //#region 🔖️Recover
    async fn build_valid_session_file(dir: &Path, name: &str) -> std::path::PathBuf {
        let path = dir.join(name);
        let doc_payload = b"recoverable document body";
        let chunk_payload = b"recoverable chunk payload";

        let mut writer = StreamingPackWriter::create(&path, &no_compression_options()).await.unwrap();
        writer.write_segment(KIND_DOCUMENT, doc_payload).await.unwrap();
        let mut chunk = writer.begin_identity_chunk(chunk_payload.len()).await.unwrap();
        for fragment in chunk_payload.chunks(5) {
            chunk.write_fragment(fragment).await.unwrap();
        }
        chunk.finish().await.unwrap();

        let manifest = Manifest {
            schema_name: String::new(),
            schema_hash: [0u8; 32],
            doc_span: ByteRange { offset: crate::format::HEADER_SIZE as u64, len: uncompressed_segment_wire_len(doc_payload.len()).await },
            doc_frame_count: 1,
            symbols_span: ByteRange { offset: 0, len: 0 },
            chunk_table_span: ByteRange { offset: 0, len: 0 },
            field_index_span: ByteRange { offset: 0, len: 0 },
            uncompressed_body_len: doc_payload.len() as u64,
            field_count: 0,
            chunk_count: 0,
            symbol_count: 0,
        };
        writer.finish(&manifest).await.unwrap();
        path
    }

    #[semio_framework_async_macros::async_test]
    async fn recover_file_with_footer_stripped_still_recovers_every_body_segment() {
        let dir = scratch_dir("recover_no_footer");
        let path = build_valid_session_file(&dir, "truncated_footer.spk").await;
        let limits = PackLimits::default();

        let full_len = std::fs::metadata(&path).unwrap().len();
        let file = std::fs::OpenOptions::new().write(true).open(&path).unwrap();
        file.set_len(full_len - crate::format::FOOTER_SIZE as u64).unwrap();
        drop(file);

        // Superblock open must fail (no valid footer) — this is the scenario recover_file is for.
        let source = FilePackSource::open(&path).unwrap();
        assert!(crate::format::PackFile::open_superblock(source, &limits).await.is_err());

        let report = recover_file(&path, &limits).await.unwrap();
        // document, chunk, chunk_table (since one chunk was written), manifest, end.
        assert_eq!(report.segments_recovered, 5);
        assert!(report.bytes_recovered > 0);
        assert!(report.manifest.is_some());
    }

    #[semio_framework_async_macros::async_test]
    async fn recover_file_truncated_mid_segment_recovers_a_strict_prefix_without_panicking() {
        let dir = scratch_dir("recover_mid_segment");
        let path = build_valid_session_file(&dir, "truncated_mid.spk").await;
        let limits = PackLimits::default();

        let full_len = std::fs::metadata(&path).unwrap().len();
        // Cut well past the footer AND into the tail of the body stream, guaranteeing the
        // last segment present (the `End` marker) is itself truncated mid-frame.
        let cut_len = full_len - crate::format::FOOTER_SIZE as u64 - 3;
        let file = std::fs::OpenOptions::new().write(true).open(&path).unwrap();
        file.set_len(cut_len).unwrap();
        drop(file);

        let report = recover_file(&path, &limits).await.unwrap();
        // Fewer than the full 5 segments (document, chunk, chunk_table, manifest, end) since
        // the trailing bytes of the last segment are gone; recovery must stop cleanly there,
        // never panic, and never report more than what a full session would produce.
        assert!(report.segments_recovered < 5);
        assert!(report.segments_recovered >= 1);
    }

    #[semio_framework_async_macros::async_test]
    async fn recover_file_on_a_file_too_short_for_a_header_errors_never_panics() {
        let dir = scratch_dir("recover_too_short");
        let path = dir.join("empty.spk");
        std::fs::write(&path, b"short").unwrap();
        let limits = PackLimits::default();
        let result = recover_file(&path, &limits).await;
        assert!(matches!(result, Err(PackError::Truncated(_))));
    }
    //#endregion 🔖️Recover
}

//! 🧾️ `pack_json` — an owned, spec-correct streaming JSON reader and writer: the replacement for
//! `serde_json` inside framework crates (see `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️20/
//! INTERACTIVE-JOB-RUNTIME-REFACTOR/PHASE-9-RUNTIME-DEPENDENCY-REMOVAL/📓️p9b-owned-serialization.md`).
//!
//! Scope, deliberately: a whole-document [`Value`] tree (parse/write), built on top of a
//! token-at-a-time [`Lexer`] so a future chunked-`Read` streaming API can be layered on without a
//! rewrite — no consumer needs multi-buffer incremental parsing today, so that layer itself is NOT
//! built (see the ticket doc's "deliberately not built" section). NOT built either: pretty-printing
//! (no consumer wants indented output), `$ref`/schema composition keywords (the sibling validator in
//! `semio-framework-schema` only needs the keyword subset it actually exercises), arbitrary-precision
//! integers (JSON numbers outside `[i64::MIN, u64::MAX]` fall back to `f64`, exactly like
//! `serde_json` without its `arbitrary_precision` feature — the only configuration this repo ever
//! built with).
//!
//! Number formatting is byte-identical to `serde_json`'s own (`zmij`-based) writer for every
//! `f64`: the fixed/exponential split follows `zmij`'s rule (`-5 <= exponent <= 15` stays fixed),
//! not ECMA-262's `Number::toString` (`-6 <= e < 21`) — the two differ, and only `zmij`'s matches
//! this repo's actual `serde_json` dependency — and the digits themselves are recomputed by exact
//! round-half-to-even arithmetic so a genuine last-digit tie always resolves the same way `zmij`
//! resolves it (proof: `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️09/☀️01/
//! RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS/🔍️research/📓️float-format-parity.md`).
//! A float and an integer of the same magnitude are still never spelled the same way (`42.0`
//! always keeps its `.0`). NaN/±Infinity — not representable in JSON — encode as `null`, matching
//! `serde_json`'s own behaviour (verified by the differential tests below).

use std::fmt;

use protocol::value::{DslValue, FromValue, ValueError};
pub use protocol::value::ToValue;

//#region 🔖️Errors
/// 🚨️ Every parse failure this crate can produce, with a byte offset into the input.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum JsonError {
    UnexpectedEof,
    UnexpectedByte { found: u8, offset: usize },
    InvalidNumber(usize),
    InvalidEscape(usize),
    InvalidUnicodeEscape(usize),
    UnpairedSurrogate(usize),
    ControlCharacterInString { byte: u8, offset: usize },
    InvalidUtf8,
    TrailingData(usize),
    MaxDepthExceeded(u32),
}

impl fmt::Display for JsonError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::UnexpectedEof => formatter.write_str("unexpected end of input"),
            Self::UnexpectedByte { found, offset } => write!(formatter, "unexpected byte {found:?} at offset {offset}"),
            Self::InvalidNumber(offset) => write!(formatter, "invalid number literal at offset {offset}"),
            Self::InvalidEscape(offset) => write!(formatter, "invalid escape sequence at offset {offset}"),
            Self::InvalidUnicodeEscape(offset) => write!(formatter, "invalid \\u escape at offset {offset}"),
            Self::UnpairedSurrogate(offset) => write!(formatter, "unpaired UTF-16 surrogate at offset {offset}"),
            Self::ControlCharacterInString { byte, offset } => write!(formatter, "control character 0x{byte:02x} in string at offset {offset}"),
            Self::InvalidUtf8 => formatter.write_str("invalid UTF-8 in input"),
            Self::TrailingData(offset) => write!(formatter, "trailing data at offset {offset}"),
            Self::MaxDepthExceeded(depth) => write!(formatter, "maximum nesting depth {depth} exceeded"),
        }
    }
}

impl std::error::Error for JsonError {}

/// 🛡️ Recursion ceiling for nested arrays/objects — matches `serde_json`'s own default
/// (128), the value this repo's fixtures were authored against.
pub const MAX_DEPTH: u32 = 128;
//#endregion 🔖️Errors

//#region 🔖️Number
/// 🔢️ A JSON number, keeping the writer's-eye distinction JSON itself does not: an integer
/// literal (`UInt`/`Int`) round-trips without a decimal point, a `Float` always carries one (or an
/// exponent) so `42` and `42.0` are never confused on the wire.
#[derive(Clone, Copy, Debug)]
pub enum Number {
    UInt(u64),
    Int(i64),
    Float(f64),
}

impl Number {
    /// 🔎️ Widens to `f64` regardless of variant — lossy for `u64`/`i64` magnitudes beyond 2^53.
    pub fn as_f64(&self) -> f64 {
        match *self {
            Number::UInt(v) => v as f64,
            Number::Int(v) => v as f64,
            Number::Float(v) => v,
        }
    }

    /// 🔎️ Exact `i64`, only for the `Int` variant and `UInt` values that fit.
    pub fn as_i64(&self) -> Option<i64> {
        match *self {
            Number::Int(v) => Some(v),
            Number::UInt(v) => i64::try_from(v).ok(),
            Number::Float(_) => None,
        }
    }

    /// 🔎️ Exact `u64`, only for the `UInt` variant and non-negative `Int` values.
    pub fn as_u64(&self) -> Option<u64> {
        match *self {
            Number::UInt(v) => Some(v),
            Number::Int(v) => u64::try_from(v).ok(),
            Number::Float(_) => None,
        }
    }

    /// 🔎️ Whether this literal was written without a decimal point or exponent.
    pub fn is_integer(&self) -> bool {
        !matches!(self, Number::Float(_))
    }
}

impl PartialEq for Number {
    fn eq(&self, other: &Self) -> bool {
        match (*self, *other) {
            (Number::UInt(a), Number::UInt(b)) => a == b,
            (Number::Int(a), Number::Int(b)) => a == b,
            (Number::Float(a), Number::Float(b)) => a == b,
            (Number::UInt(a), Number::Int(b)) | (Number::Int(b), Number::UInt(a)) => i64::try_from(a).is_ok_and(|a| a == b),
            _ => false,
        }
    }
}

impl From<u64> for Number {
    fn from(v: u64) -> Self {
        Number::UInt(v)
    }
}
impl From<i64> for Number {
    fn from(v: i64) -> Self {
        Number::Int(v)
    }
}
impl From<f64> for Number {
    fn from(v: f64) -> Self {
        Number::Float(v)
    }
}
impl From<u32> for Number {
    fn from(v: u32) -> Self {
        Number::UInt(v as u64)
    }
}
impl From<i32> for Number {
    fn from(v: i32) -> Self {
        Number::Int(v as i64)
    }
}
impl From<usize> for Number {
    fn from(v: usize) -> Self {
        Number::UInt(v as u64)
    }
}
impl From<i8> for Number {
    fn from(v: i8) -> Self {
        Number::Int(v as i64)
    }
}
//#endregion 🔖️Number

//#region 🔖️Value
/// 🗂️ An insertion-order-preserving JSON object. Re-inserting an existing key overwrites
/// its value in place (last-value-wins) rather than moving it to the end — the same externally
/// observable behaviour as `serde_json::Map`'s default `BTreeMap` backing, just order-preserving
/// for the common no-duplicate case instead of key-sorted.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Object(Vec<(String, Value)>);

impl Object {
    pub fn new() -> Self {
        Self(Vec::new())
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        self.0.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    }

    pub fn get_mut(&mut self, key: &str) -> Option<&mut Value> {
        self.0.iter_mut().find(|(k, _)| k == key).map(|(_, v)| v)
    }

    pub fn contains_key(&self, key: &str) -> bool {
        self.get(key).is_some()
    }

    pub fn insert(&mut self, key: impl Into<String>, value: Value) -> Option<Value> {
        let key = key.into();
        if let Some(slot) = self.0.iter_mut().find(|(k, _)| *k == key) {
            return Some(std::mem::replace(&mut slot.1, value));
        }
        self.0.push((key, value));
        None
    }

    pub fn len(&self) -> usize {
        self.0.len()
    }

    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    /// 🗑️ Removes `key` and returns its value, preserving the insertion order of the rest.
    ///
    /// Mirrors `serde_json::Map::remove` so a recursive key-at-a-time retirement walk can be
    /// expressed against this type without reaching for serde_json.
    pub fn remove(&mut self, key: &str) -> Option<Value> {
        let index = self.0.iter().position(|(name, _)| name == key)?;
        Some(self.0.remove(index).1)
    }

    /// ✏️ Mutable iteration in insertion order, for in-place rewrites of nested values.
    pub fn iter_mut(&mut self) -> impl Iterator<Item = (&str, &mut Value)> {
        self.0.iter_mut().map(|(name, value)| (name.as_str(), value))
    }

    pub fn iter(&self) -> impl Iterator<Item = (&str, &Value)> {
        self.0.iter().map(|(k, v)| (k.as_str(), v))
    }
}

impl<'a> IntoIterator for &'a Object {
    type Item = (&'a str, &'a Value);
    type IntoIter = Box<dyn Iterator<Item = (&'a str, &'a Value)> + 'a>;
    fn into_iter(self) -> Self::IntoIter {
        Box::new(self.iter())
    }
}

impl FromIterator<(String, Value)> for Object {
    fn from_iter<T: IntoIterator<Item = (String, Value)>>(iter: T) -> Self {
        let mut object = Object::new();
        for (key, value) in iter {
            object.insert(key, value);
        }
        object
    }
}

/// 🌳️ An owned JSON value tree — the `serde_json::Value` replacement. Every framework
/// consumer of dynamically-shaped JSON (schema leaves, protocol probes) reads/writes this type.
#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Number(Number),
    String(String),
    Array(Vec<Value>),
    Object(Object),
}

impl Value {
    pub fn is_null(&self) -> bool {
        matches!(self, Value::Null)
    }

    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Value::Bool(v) => Some(*v),
            _ => None,
        }
    }

    pub fn as_str(&self) -> Option<&str> {
        match self {
            Value::String(v) => Some(v.as_str()),
            _ => None,
        }
    }

    pub fn as_number(&self) -> Option<&Number> {
        match self {
            Value::Number(v) => Some(v),
            _ => None,
        }
    }

    pub fn as_f64(&self) -> Option<f64> {
        self.as_number().map(Number::as_f64)
    }

    pub fn as_i64(&self) -> Option<i64> {
        self.as_number().and_then(Number::as_i64)
    }

    pub fn as_u64(&self) -> Option<u64> {
        self.as_number().and_then(Number::as_u64)
    }

    /// 🔎️ `serde_json::Value::as_array`'s own signature (`Option<&Vec<Value>>`, not a bare slice) —
    /// on purpose: `Vec<Value>: Clone` lets `.and_then(Value::as_array).cloned()` call sites that
    /// used to target `serde_json::Value` keep compiling unchanged (`[Value]` alone is unsized and
    /// has no `Clone`).
    pub fn as_array(&self) -> Option<&Vec<Value>> {
        match self {
            Value::Array(v) => Some(v),
            _ => None,
        }
    }

    pub fn as_array_mut(&mut self) -> Option<&mut Vec<Value>> {
        match self {
            Value::Array(v) => Some(v),
            _ => None,
        }
    }

    pub fn as_object(&self) -> Option<&Object> {
        match self {
            Value::Object(v) => Some(v),
            _ => None,
        }
    }

    pub fn as_object_mut(&mut self) -> Option<&mut Object> {
        match self {
            Value::Object(v) => Some(v),
            _ => None,
        }
    }

    /// 🔎️ Object-field lookup, mirroring `serde_json::Value::get` — `None` on any non-object.
    pub fn get(&self, key: &str) -> Option<&Value> {
        self.as_object().and_then(|object| object.get(key))
    }

    pub fn get_mut(&mut self, key: &str) -> Option<&mut Value> {
        self.as_object_mut().and_then(|object| object.get_mut(key))
    }

    /// 🔎️ Array-element lookup by position, mirroring `serde_json::Value::get(usize)` —
    /// `None` on any non-array or out-of-bounds index.
    pub fn get_index(&self, index: usize) -> Option<&Value> {
        self.as_array().and_then(|array| array.get(index))
    }

    /// 🧭️ RFC 6901 JSON Pointer lookup, mirroring `serde_json::Value::pointer` — the empty string
    /// resolves to `self`; a non-empty pointer must start with `/`, and each `/`-separated segment
    /// is unescaped (`~1` -> `/`, `~0` -> `~`) before being tried as an object key, then as an
    /// array index. `None` on a malformed pointer, a missing key, or an out-of-range index.
    pub fn pointer(&self, pointer: &str) -> Option<&Value> {
        if pointer.is_empty() {
            return Some(self);
        }
        if !pointer.starts_with('/') {
            return None;
        }
        pointer.split('/').skip(1).try_fold(self, |current, raw_segment| {
            let segment = raw_segment.replace("~1", "/").replace("~0", "~");
            match current {
                Value::Object(_) => current.get(&segment),
                Value::Array(_) => segment.parse::<usize>().ok().and_then(|index| current.get_index(index)),
                _ => None,
            }
        })
    }
}

/// 🗝️ `value["key"]`, mirroring `serde_json::Value`'s own `Index<&str>` — panics if `self` is
/// not an object, returns [`Value::Null`] for a missing key (never panics on a missing key,
/// matching `serde_json`'s own permissive lookup semantics for assertions/fixtures).
impl std::ops::Index<&str> for Value {
    type Output = Value;
    fn index(&self, key: &str) -> &Value {
        static NULL: Value = Value::Null;
        match self.get(key) {
            Some(value) => value,
            None => &NULL,
        }
    }
}

/// 🗝️ `value[index]`, mirroring `serde_json::Value`'s own `Index<usize>` — panics if `self` is
/// not an array, returns [`Value::Null`] for an out-of-bounds index.
impl std::ops::Index<usize> for Value {
    type Output = Value;
    fn index(&self, index: usize) -> &Value {
        static NULL: Value = Value::Null;
        match self.get_index(index) {
            Some(value) => value,
            None => &NULL,
        }
    }
}

/// 🪞️ Cross-type equality against Rust primitives, mirroring `serde_json::Value`'s own
/// `impl_value_eq!` family — lets `assert_eq!(value["key"], "literal")`/`value == 3.0` read
/// exactly like the `serde_json` call sites they replace, with no `.as_str()`/`.as_f64()` unwrap
/// noise at the assertion site.
macro_rules! impl_value_partial_eq {
    ($($ty:ty => $variant_check:expr),+ $(,)?) => {
        $(
            impl PartialEq<$ty> for Value {
                fn eq(&self, other: &$ty) -> bool {
                    ($variant_check)(self, other)
                }
            }
            impl PartialEq<Value> for $ty {
                fn eq(&self, other: &Value) -> bool {
                    ($variant_check)(other, self)
                }
            }
        )+
    };
}

impl_value_partial_eq! {
    str => |value: &Value, other: &str| value.as_str() == Some(other),
    String => |value: &Value, other: &String| value.as_str() == Some(other.as_str()),
    bool => |value: &Value, other: &bool| value.as_bool() == Some(*other),
    f64 => |value: &Value, other: &f64| value.as_f64() == Some(*other),
    i64 => |value: &Value, other: &i64| value.as_i64() == Some(*other),
    u64 => |value: &Value, other: &u64| value.as_u64() == Some(*other),
    i32 => |value: &Value, other: &i32| value.as_i64() == Some(*other as i64),
    u32 => |value: &Value, other: &u32| value.as_u64() == Some(*other as u64),
    usize => |value: &Value, other: &usize| value.as_u64() == Some(*other as u64),
}

impl PartialEq<&str> for Value {
    fn eq(&self, other: &&str) -> bool {
        self.as_str() == Some(*other)
    }
}
impl PartialEq<Value> for &str {
    fn eq(&self, other: &Value) -> bool {
        other.as_str() == Some(*self)
    }
}

impl From<bool> for Value {
    fn from(v: bool) -> Self {
        Value::Bool(v)
    }
}
impl From<&str> for Value {
    fn from(v: &str) -> Self {
        Value::String(v.to_string())
    }
}
impl From<String> for Value {
    fn from(v: String) -> Self {
        Value::String(v)
    }
}
impl From<u64> for Value {
    fn from(v: u64) -> Self {
        Value::Number(Number::UInt(v))
    }
}
impl From<i64> for Value {
    fn from(v: i64) -> Self {
        Value::Number(Number::Int(v))
    }
}
impl From<f64> for Value {
    fn from(v: f64) -> Self {
        Value::Number(Number::Float(v))
    }
}
impl From<u32> for Value {
    fn from(v: u32) -> Self {
        Value::Number(Number::UInt(v as u64))
    }
}
impl From<i32> for Value {
    fn from(v: i32) -> Self {
        Value::Number(Number::Int(v as i64))
    }
}
impl From<usize> for Value {
    fn from(v: usize) -> Self {
        Value::Number(Number::UInt(v as u64))
    }
}
impl From<i8> for Value {
    fn from(v: i8) -> Self {
        Value::Number(Number::Int(v as i64))
    }
}
impl From<Vec<Value>> for Value {
    fn from(v: Vec<Value>) -> Self {
        Value::Array(v)
    }
}
impl From<Object> for Value {
    fn from(v: Object) -> Self {
        Value::Object(v)
    }
}
impl<T: Into<Value>> From<Option<T>> for Value {
    fn from(v: Option<T>) -> Self {
        match v {
            Some(inner) => inner.into(),
            None => Value::Null,
        }
    }
}

/// 🏗️ Builds a [`Value::Array`] from any iterator of values.
pub fn array(items: impl IntoIterator<Item = Value>) -> Value {
    Value::Array(items.into_iter().collect())
}

/// 🏗️ Builds a [`Value::Object`] from any iterator of `(key, value)` pairs.
pub fn object(pairs: impl IntoIterator<Item = (String, Value)>) -> Value {
    Value::Object(pairs.into_iter().collect())
}

/// ⚖️ Structural equality that ignores object key order — [`Object`]'s derived `PartialEq`
/// (insertion-order `Vec`-backed) is order-sensitive, unlike `serde_json::Map`'s default
/// key-sorted `BTreeMap` backing; a decode→re-encode round trip through [`crate::json::to_json_string`]
/// naturally reorders fields to Rust struct declaration order, so a "committed JSON is already
/// canonical" style assertion needs this, not `==`, to match the old serde-era test semantics.
pub fn value_eq_ignoring_object_order(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(key, value)| y.get(key).is_some_and(|other| value_eq_ignoring_object_order(value, other)))
        }
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y.iter()).all(|(l, r)| value_eq_ignoring_object_order(l, r)),
        _ => a == b,
    }
}
//#endregion 🔖️Value

//#region 🔖️DslValueBridge
/// 🌉️ Structural conversion from `protocol::value::DslValue` (the in-memory tree
/// `ToValue`/`FromValue` target onto — see `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️09/☀️01/
/// RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS/🔍️research/
/// 📓️serde-replacement-surface.md` §"pack::json::Value ↔ DslValue conversion") into this crate's
/// own JSON-text-oriented [`Value`] — the two are sibling shapes with no shared type, so a
/// `Mutation`/`MutationDiff` payload that needs literal JSON **text** (a wire byte string, not
/// just an in-memory value) walks through here on the way to [`to_string`]/[`parse`].
/// Maps `protocol::value::Number`'s `UInt`/`Int`/`Float` variants onto this crate's own
/// identically-shaped [`Number`] one-for-one — an integer stays an integer across the bridge
/// instead of being widened to `f64` and printed back with a spurious `.0`.
pub fn from_dsl_value(value: &DslValue) -> Value {
    match value {
        DslValue::Null => Value::Null,
        DslValue::Bool(b) => Value::Bool(*b),
        DslValue::Number(n) => Value::Number(match n {
            protocol::value::Number::UInt(value) => Number::UInt(*value),
            protocol::value::Number::Int(value) => Number::Int(*value),
            protocol::value::Number::Float(value) => Number::Float(*value),
        }),
        DslValue::String(s) => Value::String(s.clone()),
        DslValue::Bytes(bytes) => Value::Array(bytes.iter().map(|byte|Value::Number(Number::UInt(u64::from(*byte)))).collect()),
        DslValue::Array(items) => Value::Array(items.iter().map(from_dsl_value).collect()),
        DslValue::Object(entries) => Value::Object(entries.iter().map(|(key, value)| (key.clone(), from_dsl_value(value))).collect()),
    }
}

/// 🌉️ The reverse of [`from_dsl_value`] — maps numbers variant-for-variant, so an integer stays an
/// integer across the bridge instead of being widened to `f64` and printed back as `1.0`.
pub fn to_dsl_value(value: &Value) -> DslValue {
    match value {
        Value::Null => DslValue::Null,
        Value::Bool(b) => DslValue::Bool(*b),
        Value::Number(n) => DslValue::Number(match n {
            Number::UInt(value) => protocol::value::Number::UInt(*value),
            Number::Int(value) => protocol::value::Number::Int(*value),
            Number::Float(value) => protocol::value::Number::Float(*value),
        }),
        Value::String(s) => DslValue::String(s.clone()),
        Value::Array(items) => DslValue::Array(items.iter().map(to_dsl_value).collect()),
        Value::Object(entries) => DslValue::object(entries.iter().map(|(key, value)| (key.to_string(), to_dsl_value(value)))),
    }
}
impl ToValue for Value {
    fn to_value(&self) -> DslValue {
        to_dsl_value(self)
    }
}

impl FromValue for Value {
    fn from_value(value: DslValue) -> Result<Self, ValueError> {
        Ok(from_dsl_value(&value))
    }
}

impl ToValue for Object {
    fn to_value(&self) -> DslValue {
        DslValue::object(self.iter().map(|(key, value)| (key.to_string(), value.to_value())))
    }
}
//#endregion 🔖️DslValueBridge

//#region 🔖️Lexer
/// 🪙️ One structural token — the streaming layer everything else is built on. A future
/// chunked-`Read` streaming API would produce these incrementally across buffer refills; today's
/// `Lexer` already tokenizes without materializing the whole document as a DOM first, it just still
/// requires the whole input as one contiguous `&str` (every framework consumer today hands over a
/// short handcrafted schema leaf, never something worth reading in chunks).
#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Null,
    True,
    False,
    Number(Number),
    String(String),
    ArrayStart,
    ArrayEnd,
    ObjectStart,
    ObjectEnd,
    Comma,
    Colon,
}

/// 🔤️ Token-at-a-time reader over a `&str` — zero-copy for structural bytes, allocating
/// only for string/number token payloads.
pub struct Lexer<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Lexer<'a> {
    pub fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    /// 🔎️ Current byte offset into the input.
    pub fn position(&self) -> usize {
        self.pos
    }

    fn peek_byte(&self) -> Option<u8> {
        self.input.as_bytes().get(self.pos).copied()
    }

    fn skip_ws(&mut self) {
        while matches!(self.peek_byte(), Some(b' ' | b'\t' | b'\n' | b'\r')) {
            self.pos += 1;
        }
    }

    fn read_literal(&mut self, literal: &'static str, token: Token) -> Result<Option<Token>, JsonError> {
        if self.input[self.pos..].starts_with(literal) {
            self.pos += literal.len();
            Ok(Some(token))
        } else {
            Err(JsonError::UnexpectedByte { found: self.peek_byte().unwrap_or(0), offset: self.pos })
        }
    }

    /// 🔢️ Reads one JSON number literal per RFC 8259 §6: `-? int frac? exp?`, no leading zeros.
    /// Falls back to `Number::Float` whenever a fractional part, exponent, or `u64`/`i64` overflow
    /// is present — identical to `serde_json` with its `float_roundtrip` oracle configuration and
    /// without `arbitrary_precision` (the only configuration this repo ever builds with).
    fn read_number(&mut self) -> Result<Token, JsonError> {
        let start = self.pos;
        let negative = self.peek_byte() == Some(b'-');
        if negative {
            self.pos += 1;
        }
        match self.peek_byte() {
            Some(b'0') => self.pos += 1,
            Some(b'1'..=b'9') => {
                while matches!(self.peek_byte(), Some(b'0'..=b'9')) {
                    self.pos += 1;
                }
            }
            _ => return Err(JsonError::InvalidNumber(start)),
        }
        let mut is_float = false;
        if self.peek_byte() == Some(b'.') {
            is_float = true;
            self.pos += 1;
            let frac_start = self.pos;
            while matches!(self.peek_byte(), Some(b'0'..=b'9')) {
                self.pos += 1;
            }
            if self.pos == frac_start {
                return Err(JsonError::InvalidNumber(start));
            }
        }
        if matches!(self.peek_byte(), Some(b'e' | b'E')) {
            is_float = true;
            self.pos += 1;
            if matches!(self.peek_byte(), Some(b'+' | b'-')) {
                self.pos += 1;
            }
            let exp_start = self.pos;
            while matches!(self.peek_byte(), Some(b'0'..=b'9')) {
                self.pos += 1;
            }
            if self.pos == exp_start {
                return Err(JsonError::InvalidNumber(start));
            }
        }
        let text = &self.input[start..self.pos];
        if is_float {
            let value: f64 = text.parse().map_err(|_| JsonError::InvalidNumber(start))?;
            if !value.is_finite() {
                return Err(JsonError::InvalidNumber(start));
            }
            return Ok(Token::Number(Number::Float(value)));
        }
        if !negative {
            if let Ok(value) = text.parse::<u64>() {
                return Ok(Token::Number(Number::UInt(value)));
            }
        } else if let Ok(value) = text.parse::<i64>() {
            return Ok(Token::Number(Number::Int(value)));
        }
        let value: f64 = text.parse().map_err(|_| JsonError::InvalidNumber(start))?;
        if !value.is_finite() {
            return Err(JsonError::InvalidNumber(start));
        }
        Ok(Token::Number(Number::Float(value)))
    }

    /// 🧵️ Reads the 4 hex digits of one `\uXXXX` escape (already past the `u`).
    fn read_hex4(&mut self, escape_start: usize) -> Result<u32, JsonError> {
        let bytes = self.input.as_bytes();
        if self.pos + 4 > bytes.len() {
            return Err(JsonError::InvalidUnicodeEscape(escape_start));
        }
        let mut value: u32 = 0;
        for &byte in &bytes[self.pos..self.pos + 4] {
            let digit = match byte {
                b'0'..=b'9' => u32::from(byte - b'0'),
                b'a'..=b'f' => u32::from(byte - b'a') + 10,
                b'A'..=b'F' => u32::from(byte - b'A') + 10,
                _ => return Err(JsonError::InvalidUnicodeEscape(escape_start)),
            };
            value = value * 16 + digit;
        }
        self.pos += 4;
        Ok(value)
    }

    /// 🧵️ Reads a full JSON string literal (opening quote must be at `self.pos`). Handles every
    /// short escape, `\uXXXX`, and UTF-16 surrogate pairs for supplementary-plane characters —
    /// rejects a lone (unpaired) surrogate rather than silently producing an invalid `char`.
    fn read_string(&mut self) -> Result<String, JsonError> {
        self.pos += 1; // opening quote
        let mut out = String::new();
        loop {
            let rest = &self.input[self.pos..];
            let ch = rest.chars().next().ok_or(JsonError::UnexpectedEof)?;
            match ch {
                '"' => {
                    self.pos += 1;
                    return Ok(out);
                }
                '\\' => {
                    let escape_start = self.pos;
                    self.pos += 1;
                    let escape_char = self.input[self.pos..].chars().next().ok_or(JsonError::UnexpectedEof)?;
                    self.pos += escape_char.len_utf8();
                    match escape_char {
                        '"' => out.push('"'),
                        '\\' => out.push('\\'),
                        '/' => out.push('/'),
                        'b' => out.push('\u{0008}'),
                        'f' => out.push('\u{000C}'),
                        'n' => out.push('\n'),
                        'r' => out.push('\r'),
                        't' => out.push('\t'),
                        'u' => {
                            let unit = self.read_hex4(escape_start)?;
                            if (0xD800..=0xDBFF).contains(&unit) {
                                if self.peek_byte() != Some(b'\\') {
                                    return Err(JsonError::UnpairedSurrogate(escape_start));
                                }
                                self.pos += 1;
                                if self.peek_byte() != Some(b'u') {
                                    return Err(JsonError::UnpairedSurrogate(escape_start));
                                }
                                self.pos += 1;
                                let low = self.read_hex4(escape_start)?;
                                if !(0xDC00..=0xDFFF).contains(&low) {
                                    return Err(JsonError::UnpairedSurrogate(escape_start));
                                }
                                let scalar = 0x10000 + ((unit - 0xD800) << 10) + (low - 0xDC00);
                                out.push(char::from_u32(scalar).ok_or(JsonError::UnpairedSurrogate(escape_start))?);
                            } else if (0xDC00..=0xDFFF).contains(&unit) {
                                return Err(JsonError::UnpairedSurrogate(escape_start));
                            } else {
                                out.push(char::from_u32(unit).ok_or(JsonError::InvalidUnicodeEscape(escape_start))?);
                            }
                        }
                        _ => return Err(JsonError::InvalidEscape(escape_start)),
                    }
                }
                control if (control as u32) < 0x20 => {
                    return Err(JsonError::ControlCharacterInString { byte: control as u8, offset: self.pos });
                }
                other => {
                    out.push(other);
                    self.pos += other.len_utf8();
                }
            }
        }
    }

    /// 📤️ Reads the next structural or scalar token, or `None` at end of input.
    pub fn next_token(&mut self) -> Result<Option<Token>, JsonError> {
        self.skip_ws();
        let Some(byte) = self.peek_byte() else { return Ok(None) };
        match byte {
            b'{' => {
                self.pos += 1;
                Ok(Some(Token::ObjectStart))
            }
            b'}' => {
                self.pos += 1;
                Ok(Some(Token::ObjectEnd))
            }
            b'[' => {
                self.pos += 1;
                Ok(Some(Token::ArrayStart))
            }
            b']' => {
                self.pos += 1;
                Ok(Some(Token::ArrayEnd))
            }
            b',' => {
                self.pos += 1;
                Ok(Some(Token::Comma))
            }
            b':' => {
                self.pos += 1;
                Ok(Some(Token::Colon))
            }
            b'"' => self.read_string().map(|s| Some(Token::String(s))),
            b't' => self.read_literal("true", Token::True),
            b'f' => self.read_literal("false", Token::False),
            b'n' => self.read_literal("null", Token::Null),
            b'-' | b'0'..=b'9' => self.read_number().map(Some),
            _ => Err(JsonError::UnexpectedByte { found: byte, offset: self.pos }),
        }
    }
}
//#endregion 🔖️Lexer

//#region 🔖️Parser
/// 🌳️ Parses one whole JSON document from `input`, rejecting trailing non-whitespace bytes.
// 🚫️async: R9 pure in-memory parse, no I/O.
pub fn parse(input: &str) -> Result<Value, JsonError> {
    let mut lexer = Lexer::new(input);
    let value = parse_value(&mut lexer, 0)?;
    lexer.skip_ws();
    if lexer.pos < lexer.input.len() {
        return Err(JsonError::TrailingData(lexer.pos));
    }
    Ok(value)
}

/// 🌳️ [`parse`] over raw bytes — errors with [`JsonError::InvalidUtf8`] if `input` is not UTF-8.
pub fn parse_bytes(input: &[u8]) -> Result<Value, JsonError> {
    let text = std::str::from_utf8(input).map_err(|_| JsonError::InvalidUtf8)?;
    parse(text)
}

fn parse_value(lexer: &mut Lexer<'_>, depth: u32) -> Result<Value, JsonError> {
    if depth > MAX_DEPTH {
        return Err(JsonError::MaxDepthExceeded(MAX_DEPTH));
    }
    lexer.skip_ws();
    let offset = lexer.pos;
    let token = lexer.next_token()?.ok_or(JsonError::UnexpectedEof)?;
    match token {
        Token::Null => Ok(Value::Null),
        Token::True => Ok(Value::Bool(true)),
        Token::False => Ok(Value::Bool(false)),
        Token::Number(number) => Ok(Value::Number(number)),
        Token::String(text) => Ok(Value::String(text)),
        Token::ArrayStart => parse_array(lexer, depth + 1),
        Token::ObjectStart => parse_object(lexer, depth + 1),
        Token::ObjectEnd | Token::ArrayEnd | Token::Comma | Token::Colon => Err(JsonError::UnexpectedByte { found: lexer.input.as_bytes()[offset], offset }),
    }
}

fn parse_array(lexer: &mut Lexer<'_>, depth: u32) -> Result<Value, JsonError> {
    let mut items = Vec::new();
    lexer.skip_ws();
    if lexer.peek_byte() == Some(b']') {
        lexer.pos += 1;
        return Ok(Value::Array(items));
    }
    loop {
        items.push(parse_value(lexer, depth)?);
        lexer.skip_ws();
        match lexer.peek_byte() {
            Some(b',') => lexer.pos += 1,
            Some(b']') => {
                lexer.pos += 1;
                return Ok(Value::Array(items));
            }
            Some(other) => return Err(JsonError::UnexpectedByte { found: other, offset: lexer.pos }),
            None => return Err(JsonError::UnexpectedEof),
        }
    }
}

fn parse_object(lexer: &mut Lexer<'_>, depth: u32) -> Result<Value, JsonError> {
    let mut object = Object::new();
    lexer.skip_ws();
    if lexer.peek_byte() == Some(b'}') {
        lexer.pos += 1;
        return Ok(Value::Object(object));
    }
    loop {
        lexer.skip_ws();
        if lexer.peek_byte() != Some(b'"') {
            return Err(JsonError::UnexpectedByte { found: lexer.peek_byte().unwrap_or(0), offset: lexer.pos });
        }
        let key = lexer.read_string()?;
        lexer.skip_ws();
        if lexer.peek_byte() != Some(b':') {
            return Err(JsonError::UnexpectedByte { found: lexer.peek_byte().unwrap_or(0), offset: lexer.pos });
        }
        lexer.pos += 1;
        let value = parse_value(lexer, depth)?;
        object.insert(key, value);
        lexer.skip_ws();
        match lexer.peek_byte() {
            Some(b',') => lexer.pos += 1,
            Some(b'}') => {
                lexer.pos += 1;
                return Ok(Value::Object(object));
            }
            Some(other) => return Err(JsonError::UnexpectedByte { found: other, offset: lexer.pos }),
            None => return Err(JsonError::UnexpectedEof),
        }
    }
}
//#endregion 🔖️Parser

//#region 🔖️Writer
/// ✍️ Writes `value` as compact JSON.
// 🚫️async: R9 pure in-memory format, no I/O.
pub fn to_string(value: &Value) -> String {
    let mut out = String::new();
    write_value(value, &mut out);
    out
}

/// ✍️ Writes `value` as 2-space-indented JSON, matching `serde_json::to_string_pretty`'s own
/// layout (`": "` after object keys, one array/object member per line, no trailing newline) — the
/// `serde_json::to_string_pretty` replacement every human-facing JSON view (an example-document
/// viewer, an exported fixture, a rule inspector) still needs even after its call site stops
/// depending on `serde_json` for everything else.
// 🚫️async: R9 pure in-memory format, no I/O.
pub fn to_string_pretty(value: &Value) -> String {
    let mut out = String::new();
    write_value_pretty(value, &mut out, 0);
    out
}

fn write_indent(out: &mut String, depth: usize) {
    for _ in 0..depth {
        out.push_str("  ");
    }
}

fn write_value_pretty(value: &Value, out: &mut String, depth: usize) {
    match value {
        Value::Array(items) if !items.is_empty() => {
            out.push_str("[\n");
            for (index, item) in items.iter().enumerate() {
                if index > 0 {
                    out.push_str(",\n");
                }
                write_indent(out, depth + 1);
                write_value_pretty(item, out, depth + 1);
            }
            out.push('\n');
            write_indent(out, depth);
            out.push(']');
        }
        Value::Object(object) if !object.is_empty() => {
            out.push_str("{\n");
            for (index, (key, value)) in object.iter().enumerate() {
                if index > 0 {
                    out.push_str(",\n");
                }
                write_indent(out, depth + 1);
                write_string(key, out);
                out.push_str(": ");
                write_value_pretty(value, out, depth + 1);
            }
            out.push('\n');
            write_indent(out, depth);
            out.push('}');
        }
        other => write_value(other, out),
    }
}

/// 🪞️ `value.to_string()`/`format!("{value}")`, mirroring `serde_json::Value`'s own `Display` —
/// every plugin call site that used to write `serde_json::json!({...}).to_string()` keeps
/// compiling unchanged against `pack::json!({...}).to_string()`.
impl fmt::Display for Value {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&to_string(self))
    }
}

fn write_value(value: &Value, out: &mut String) {
    match value {
        Value::Null => out.push_str("null"),
        Value::Bool(true) => out.push_str("true"),
        Value::Bool(false) => out.push_str("false"),
        Value::Number(number) => write_number(*number, out),
        Value::String(text) => write_string(text, out),
        Value::Array(items) => {
            out.push('[');
            for (index, item) in items.iter().enumerate() {
                if index > 0 {
                    out.push(',');
                }
                write_value(item, out);
            }
            out.push(']');
        }
        Value::Object(object) => {
            out.push('{');
            for (index, (key, value)) in object.iter().enumerate() {
                if index > 0 {
                    out.push(',');
                }
                write_string(key, out);
                out.push(':');
                write_value(value, out);
            }
            out.push('}');
        }
    }
}

/// ✍️ Escapes `"`, `\`, and control characters (`\b \f \n \r \t` shorthands, `\u00XX` otherwise);
/// everything else — including non-ASCII — passes through unescaped, matching `serde_json`'s
/// default (`ensure_ascii`-off) writer.
fn write_string(text: &str, out: &mut String) {
    out.push('"');
    for ch in text.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{0008}' => out.push_str("\\b"),
            '\u{000C}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            control if (control as u32) < 0x20 => {
                use fmt::Write as _;
                let _ = write!(out, "\\u{:04x}", control as u32);
            }
            other => out.push(other),
        }
    }
    out.push('"');
}

fn write_number(number: Number, out: &mut String) {
    match number {
        Number::UInt(value) => {
            use fmt::Write as _;
            let _ = write!(out, "{value}");
        }
        Number::Int(value) => {
            use fmt::Write as _;
            let _ = write!(out, "{value}");
        }
        Number::Float(value) => write_float(value, out),
    }
}

/// ✍️ `serde_json`'s own (`zmij`-based) fixed/exponential split for `f64`: fixed notation for
/// `-5 <= exponent <= 15` on the leading-digit decimal exponent, exponential otherwise — traced
/// by hand from `zmij 1.0.21`'s `write<Float>` (`~/.cargo/registry/…/zmij-1.0.21/src/lib.rs`,
/// the `(-5..=15).contains(&dec_exp)` guard) and confirmed against the pinned resolved version in
/// this workspace's own `Cargo.lock`. Not ECMA-262's `-6 <= e < 21` (that was this writer's prior,
/// wrong rule — ties in the last significant digit alone hid the boundary-case fanout it caused).
/// A whole-number float always gets an explicit `.0` in fixed notation so it never collapses onto
/// its integer twin on the wire. See `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️09/☀️01/
/// RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS/🔍️research/📓️float-format-parity.md`.
fn write_float(value: f64, out: &mut String) {
    write_float_to(value, out).expect("String accepts formatted JSON floats");
}

struct ScalarText { bytes: [u8; 128], length: usize }
impl ScalarText {
    fn new() -> Self { Self { bytes: [0; 128], length: 0 } }
    fn text(&self) -> &str { std::str::from_utf8(&self.bytes[..self.length]).expect("formatted scalar UTF-8") }
}
impl fmt::Write for ScalarText {
    fn write_str(&mut self, text: &str) -> fmt::Result {
        let end = self.length.checked_add(text.len()).filter(|end| *end <= self.bytes.len()).ok_or(fmt::Error)?;
        self.bytes[self.length..end].copy_from_slice(text.as_bytes()); self.length = end; Ok(())
    }
}

fn write_float_to(value: f64, out: &mut impl fmt::Write) -> fmt::Result {
    use fmt::Write as _;
    if !value.is_finite() {
        return out.write_str("null");
    }
    if value == 0.0 {
        return out.write_str(if value.is_sign_negative() { "-0.0" } else { "0.0" });
    }
    let negative = value.is_sign_negative();
    let magnitude = value.abs();
    let mut scientific = ScalarText::new();
    write!(scientific, "{magnitude:e}")?;
    let (mantissa_text, exponent_text) = scientific.text().split_once('e').expect("LowerExp always emits an exponent");
    let mut exponent: i32 = exponent_text.parse().expect("LowerExp exponent is always a plain integer");
    let digit_count = mantissa_text.bytes().filter(|byte| *byte != b'.').count();
    let (mut digits, exponent_adjust) = float_format::correctly_rounded_digits(magnitude, exponent, digit_count);
    exponent += exponent_adjust;
    if exponent_adjust != 0 {
        digits.truncate(digit_count);
    }
    let digit_count = digits.len() as i32;
    if negative {
        out.write_char('-')?;
    }
    if (-5..=15).contains(&exponent) {
        if exponent >= digit_count - 1 {
            out.write_str(std::str::from_utf8(&digits).expect("decimal digits are ASCII"))?;
            for _ in 0..(exponent - (digit_count - 1)) {
                out.write_char('0')?;
            }
            out.write_str(".0")?;
        } else if exponent >= 0 {
            let integer_len = (exponent + 1) as usize;
            out.write_str(std::str::from_utf8(&digits[..integer_len]).expect("decimal digits are ASCII"))?;
            out.write_char('.')?;
            out.write_str(std::str::from_utf8(&digits[integer_len..]).expect("decimal digits are ASCII"))?;
        } else {
            out.write_str("0.")?;
            for _ in 0..(-exponent - 1) {
                out.write_char('0')?;
            }
            out.write_str(std::str::from_utf8(&digits).expect("decimal digits are ASCII"))?;
        }
    } else {
        out.write_char(digits[0] as char)?;
        if digits.len() > 1 {
            out.write_char('.')?;
            out.write_str(std::str::from_utf8(&digits[1..]).expect("decimal digits are ASCII"))?;
        }
        out.write_char('e')?;
        if exponent >= 0 {
            out.write_char('+')?;
        }
        fmt::Write::write_fmt(out, format_args!("{exponent}"))?;
    }
    Ok(())
}

/// ✍️ [`write_float`] as a standalone string, for callers that write one bare JSON number
/// directly (no [`Value`] tree) — `🧵️canonical-edit::ScalarBytes` is exactly this shape:
/// a fixed-size scalar buffer, not a document.
pub fn format_f64(value: f64) -> String {
    let mut out = String::new();
    write_float(value, &mut out);
    out
}
//#endregion 🔖️Writer

//#region 🔖️FloatFormat
/// 🎯️ Exact-arithmetic correctly-rounded decimal digit generation for `f64`, used to reconcile
/// [`write_float`]'s digit string with `serde_json`'s (`zmij`'s) round-half-to-even tie-break at
/// the last significant digit — Rust's own shortest-round-trip `{:e}` formatter picks the
/// mathematically-correct-length, correctly-magnituded digit string, but at an exact
/// halfway-point tie (the true binary value sits precisely between two adjacent same-length
/// decimal strings, both of which round-trip) it does not consistently pick the even one the way
/// IEEE 754 and `zmij`'s Schubfach-based writer do. A "does a neighboring digit also round-trip"
/// probe was tried first and found unsound for large-magnitude values, where the round-trip basin
/// can hold more than two adjacent minimal-length candidates — this module instead recomputes the
/// digits directly from the value's exact rational form, `mantissa * 2^binary_exponent`, using a
/// small first-party big unsigned integer (no external bignum crate).
mod float_format {
    #[derive(Clone, Debug, PartialEq, Eq)]
    struct Limbs { values: [u32; 80], length: usize }
    impl Limbs {
        fn zeroes(length: usize) -> Self { assert!(length <= 80); Self { values: [0; 80], length } }
        fn push(&mut self, value: u32) { assert!(self.length < self.values.len()); self.values[self.length] = value; self.length += 1; }
        fn pop(&mut self) -> Option<u32> { if self.length == 0 { None } else { self.length -= 1; Some(self.values[self.length]) } }
    }
    impl std::ops::Deref for Limbs { type Target = [u32]; fn deref(&self) -> &[u32] { &self.values[..self.length] } }
    impl std::ops::DerefMut for Limbs { fn deref_mut(&mut self) -> &mut [u32] { &mut self.values[..self.length] } }
    pub(super) struct Digits { values: [u8; 32], length: usize }
    impl Digits {
        fn new() -> Self { Self { values: [0; 32], length: 0 } }
        fn push(&mut self, value: u8) { assert!(self.length < self.values.len()); self.values[self.length] = value; self.length += 1; }
        fn pop(&mut self) { assert!(self.length > 0); self.length -= 1; }
        fn prepend_zero(&mut self) { assert!(self.length < self.values.len()); self.values.copy_within(0..self.length, 1); self.values[0] = b'0'; self.length += 1; }
        pub(super) fn truncate(&mut self, length: usize) { self.length = self.length.min(length); }
    }
    impl std::ops::Deref for Digits { type Target = [u8]; fn deref(&self) -> &[u8] { &self.values[..self.length] } }
    impl std::ops::DerefMut for Digits { fn deref_mut(&mut self) -> &mut [u8] { &mut self.values[..self.length] } }
    #[derive(Clone, Debug, PartialEq, Eq)]
    struct Big(Limbs);

    impl Big {
        /// 🌱️ A single 64-bit value as a two-limb (or trimmed one-limb) big unsigned integer.
        fn from_u64(value: u64) -> Self {
            let mut limbs = Limbs::zeroes(2); limbs[0] = value as u32; limbs[1] = (value >> 32) as u32;
            Self::trim(&mut limbs);
            Big(limbs)
        }

        fn trim(limbs: &mut Limbs) {
            while limbs.len() > 1 && *limbs.last().expect("non-empty by loop condition") == 0 {
                limbs.pop();
            }
        }

        fn is_zero(&self) -> bool {
            self.0.len() == 1 && self.0[0] == 0
        }

        /// ✳️ In-place multiply by a small (`u32`-sized) factor.
        fn mul_small(&mut self, factor: u32) {
            let mut carry: u64 = 0;
            for limb in self.0.iter_mut() {
                let product = (*limb as u64) * (factor as u64) + carry;
                *limb = product as u32;
                carry = product >> 32;
            }
            if carry > 0 {
                self.0.push(carry as u32);
            }
            Self::trim(&mut self.0);
        }

        /// ✳️ In-place multiply by `5^exponent`, chunked so every factor still fits a `u32`.
        fn mul_pow5(&mut self, mut exponent: u32) {
            while exponent > 0 {
                let chunk = exponent.min(13);
                self.mul_small(5u32.pow(chunk));
                exponent -= chunk;
            }
        }

        /// ⬅️️ In-place multiply by `2^bits`.
        fn shl(&mut self, bits: u32) {
            if bits == 0 {
                return;
            }
            let limb_shift = (bits / 32) as usize;
            let bit_shift = bits % 32;
            let mut result = Limbs::zeroes(self.0.len() + limb_shift + 1);
            for (index, &limb) in self.0.iter().enumerate() {
                let value = limb as u64;
                if bit_shift == 0 {
                    result[index + limb_shift] |= value as u32;
                } else {
                    let shifted = value << bit_shift;
                    result[index + limb_shift] |= shifted as u32;
                    result[index + limb_shift + 1] |= (shifted >> 32) as u32;
                }
            }
            Self::trim(&mut result);
            self.0 = result;
        }

        fn bit_length(&self) -> u32 {
            let top = *self.0.last().expect("non-empty by construction");
            if top == 0 {
                0
            } else {
                (self.0.len() as u32 - 1) * 32 + (32 - top.leading_zeros())
            }
        }

        fn get_bit(&self, index: u32) -> bool {
            let limb = (index / 32) as usize;
            let bit = index % 32;
            if limb >= self.0.len() {
                false
            } else {
                (self.0[limb] >> bit) & 1 == 1
            }
        }

        fn cmp(&self, other: &Big) -> std::cmp::Ordering {
            if self.0.len() != other.0.len() {
                return self.0.len().cmp(&other.0.len());
            }
            for index in (0..self.0.len()).rev() {
                if self.0[index] != other.0[index] {
                    return self.0[index].cmp(&other.0[index]);
                }
            }
            std::cmp::Ordering::Equal
        }

        /// ➖️ In-place `self -= other`, requiring `self >= other`.
        fn sub_assign(&mut self, other: &Big) {
            let mut borrow: i64 = 0;
            for index in 0..self.0.len() {
                let lhs = self.0[index] as i64;
                let rhs = if index < other.0.len() { other.0[index] as i64 } else { 0 };
                let mut diff = lhs - rhs - borrow;
                if diff < 0 {
                    diff += 1 << 32;
                    borrow = 1;
                } else {
                    borrow = 0;
                }
                self.0[index] = diff as u32;
            }
            Self::trim(&mut self.0);
        }

        fn shl1(&mut self) {
            let mut carry = 0u32;
            for limb in self.0.iter_mut() {
                let next_carry = *limb >> 31;
                *limb = (*limb << 1) | carry;
                carry = next_carry;
            }
            if carry != 0 {
                self.0.push(carry);
            }
        }

        fn add_one(&mut self) {
            let mut carry = 1u64;
            for limb in self.0.iter_mut() {
                let sum = *limb as u64 + carry;
                *limb = sum as u32;
                carry = sum >> 32;
                if carry == 0 {
                    return;
                }
            }
            if carry > 0 {
                self.0.push(carry as u32);
            }
        }

        /// ➗️ Schoolbook binary long division: `self / other`, returning `(quotient, remainder)`.
        fn div_rem(&self, other: &Big) -> (Big, Big) {
            let bits = self.bit_length();
            let mut quotient = Big(Limbs::zeroes((bits / 32) as usize + 1));
            let mut remainder = Big(Limbs::zeroes(1));
            for index in (0..bits).rev() {
                remainder.shl1();
                if self.get_bit(index) {
                    remainder.0[0] |= 1;
                }
                if remainder.cmp(other) != std::cmp::Ordering::Less {
                    remainder.sub_assign(other);
                    let limb = (index / 32) as usize;
                    quotient.0[limb] |= 1 << (index % 32);
                }
            }
            Self::trim(&mut quotient.0);
            Self::trim(&mut remainder.0);
            (quotient, remainder)
        }

        fn double(&self) -> Big {
            let mut doubled = self.clone();
            doubled.shl1();
            doubled
        }

        /// 🔟️ Base-10 textual expansion, most-significant digit first, no leading zero (unless
        /// the value itself is zero).
        fn to_decimal_digits(&self) -> Digits {
            if self.is_zero() {
                let mut digits = Digits::new(); digits.push(b'0'); return digits;
            }
            let mut little_endian_digits = Digits::new();
            let mut remaining = self.clone();
            let billion = Big::from_u64(1_000_000_000);
            while !remaining.is_zero() {
                let (quotient, remainder) = remaining.div_rem(&billion);
                let mut chunk = remainder.0.iter().rev().fold(0u64, |accumulator, &limb| (accumulator << 32) | limb as u64);
                for _ in 0..9 {
                    little_endian_digits.push(b'0' + (chunk % 10) as u8);
                    chunk /= 10;
                }
                remaining = quotient;
            }
            while little_endian_digits.len() > 1 && *little_endian_digits.last().expect("non-empty by loop condition") == b'0' {
                little_endian_digits.pop();
            }
            little_endian_digits.reverse(); little_endian_digits
        }
    }

    /// 🎯️ Decomposes a finite, non-zero, non-negative `f64` into its exact
    /// `mantissa * 2^binary_exponent` form (the mantissa carries the implicit leading bit for
    /// normal numbers; subnormals keep the raw 52-bit significand at the fixed minimum exponent).
    fn decompose(magnitude: f64) -> (u64, i32) {
        let bits = magnitude.to_bits();
        let raw_exponent = ((bits >> 52) & 0x7FF) as i32;
        let raw_mantissa = bits & 0x000F_FFFF_FFFF_FFFF;
        if raw_exponent == 0 {
            (raw_mantissa, 1 - 1023 - 52)
        } else {
            (raw_mantissa | (1u64 << 52), raw_exponent - 1023 - 52)
        }
    }

    /// ✅️ The correctly-rounded (round-half-to-even) `digit_count`-digit decimal significand for
    /// `magnitude`, given the leading-digit decimal exponent `decimal_exponent` — both already
    /// established by Rust's own shortest-round-trip `{:e}` formatter, which is trusted for LENGTH
    /// and MAGNITUDE (every case in this module's own differential sweep confirms both are already
    /// correct); only the exact DIGITS at that fixed precision are recomputed here. Returns
    /// `(digits, exponent_adjust)`, where `exponent_adjust` is `1` when rounding carries all the
    /// way through (e.g. `"999"` rounds up to a truncated `"100"` with the exponent bumped), `0`
    /// otherwise.
    pub(super) fn correctly_rounded_digits(magnitude: f64, decimal_exponent: i32, digit_count: usize) -> (Digits, i32) {
        let (mantissa, binary_exponent) = decompose(magnitude);
        let scale = decimal_exponent - (digit_count as i32 - 1);
        let power_of_two = binary_exponent - scale;
        let power_of_five = -scale;

        let mut numerator = Big::from_u64(mantissa);
        if power_of_five > 0 {
            numerator.mul_pow5(power_of_five as u32);
        }
        if power_of_two > 0 {
            numerator.shl(power_of_two as u32);
        }
        let mut denominator = Big::from_u64(1);
        if power_of_five < 0 {
            denominator.mul_pow5((-power_of_five) as u32);
        }
        if power_of_two < 0 {
            denominator.shl((-power_of_two) as u32);
        }

        let (mut quotient, remainder) = numerator.div_rem(&denominator);
        let comparison = remainder.double().cmp(&denominator);
        let quotient_is_odd = quotient.0[0] & 1 == 1;
        let round_up = match comparison {
            std::cmp::Ordering::Greater => true,
            std::cmp::Ordering::Less => false,
            std::cmp::Ordering::Equal => quotient_is_odd,
        };
        if round_up {
            quotient.add_one();
        }

        let mut digit_string = quotient.to_decimal_digits();
        let mut exponent_adjust = 0;
        if digit_string.len() > digit_count {
            debug_assert_eq!(digit_string.len(), digit_count + 1, "rounding carries at most one extra digit");
            debug_assert_eq!(digit_string.last(), Some(&b'0'), "a carry past the digit budget must land on a power of ten");
            digit_string.pop();
            exponent_adjust = 1;
        }
        while digit_string.len() < digit_count {
            digit_string.prepend_zero();
        }
        (digit_string, exponent_adjust)
    }
}
//#endregion 🔖️FloatFormat

//#region 🔖️ToFromValueBridge
/// 🔤️ `serde_json::to_string`/`from_str` analogs over [`ToValue`]/[`FromValue`] instead of
/// `Serialize`/`DeserializeOwned` — layered on the structural [`from_dsl_value`]/[`to_dsl_value`]
/// walk above (`//#region 🔖️DslValueBridge`) rather than a second one: a concurrent session
/// landed that walk in this same file while this one was in flight, so this region only adds the
/// generic string convenience pair it didn't have, instead of a duplicate `DslValue <-> Value`
/// conversion. Ticket `26/09/01/RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS`: the
/// pair every plugin routes JSON text through once it stops deriving
/// `serde::Serialize`/`Deserialize` in favor of `ToValue`/`FromValue`.
pub fn to_json_string<T: ToValue>(value: &T) -> String {
    to_string(&from_dsl_value(&value.to_value()))
}

/// 🔤️ `serde_json::from_str` analog over [`FromValue`] instead of `DeserializeOwned` — a parse
/// failure and a decode failure both collapse onto [`ValueError`], matching `from_value`'s own.
pub fn from_json_str<T: FromValue>(text: &str) -> Result<T, ValueError> {
    let value = parse(text).map_err(|error| ValueError::new(error.to_string()))?;
    T::from_value(to_dsl_value(&value))
}

/// 🚦️ Parses and binds JSON under the caller's cumulative native ownership control.
pub fn from_json_str_controlled<T: FromValue>(text: &str, control: &mut protocol::value::NativeDecodeControl<'_>) -> Result<T, ValueError> {
    control.scoped_stage(|control| {
        control.begin_stage(text.len()).map_err(ValueError::new)?;
        let mut reader = ControlledReader { lexer: Lexer::new(text), control };
        let value = reader.value()?.guard_decoded(); reader.whitespace()?;
        if reader.lexer.pos != text.len() { return Err(ValueError::new(JsonError::TrailingData(reader.lexer.pos).to_string())); }
        reader.control.scoped_stage(|control| { control.begin_stage(0).map_err(ValueError::new)?; T::from_value_controlled(value.get(), control) })
    })
}

/// 🛫️ Writes ordered JSON under the caller's cumulative native ownership control.
pub fn to_json_string_controlled<T: ToValue>(value: &T, control: &mut protocol::value::NativeEncodeControl<'_>) -> Result<String, String> {
    control.scoped_stage(|control| {
        control.begin_stage(0)?; let value = value.to_value_controlled(control).map_err(|error| error.to_string())?.guard_decoded();
        let mut measure = ControlledWriter { bytes: 0, output: None }; measure.value(value.get(), control)?;
        control.charge(measure.bytes)?; let mut output = String::new(); output.try_reserve_exact(measure.bytes).map_err(|_| "controlled JSON output allocation failed")?;
        let mut writer = ControlledWriter { bytes: 0, output: Some(output) }; writer.value(value.get(), control)?;
        if writer.bytes != measure.bytes { return Err("controlled JSON output changed after admission".into()); } Ok(writer.output.unwrap())
    })
}

struct ControlledWriter { bytes: usize, output: Option<String> }
impl ControlledWriter {
    fn raw(&mut self, text: &str, control: &mut protocol::value::NativeEncodeControl<'_>) -> Result<(), String> {
        self.bytes = self.bytes.checked_add(text.len()).filter(|bytes| *bytes <= control.maximum_bytes()).ok_or("controlled JSON output exceeds caller limit")?;
        if self.output.as_ref().is_some_and(|output| self.bytes > output.capacity()) { return Err("controlled JSON output exceeds admitted allocation".into()); }
        if text.len() <= 65536 { if let Some(output) = self.output.as_mut() { output.push_str(text); } return Ok(()); }
        control.scoped_stage(|control| -> Result<(), String> { control.begin_stage(text.len())?; let mut position = 0; while position < text.len() { let mut end = position.saturating_add(65536).min(text.len()); while !text.is_char_boundary(end) { end -= 1; } if let Some(output) = self.output.as_mut() { output.push_str(&text[position..end]); } control.advance(end - position)?; position = end; } Ok(()) })
    }
    fn string(&mut self, text: &str, control: &mut protocol::value::NativeEncodeControl<'_>) -> Result<(), String> {
        self.raw("\"", control)?;
        control.scoped_stage(|control| -> Result<(), String> { control.begin_stage(text.len())?; for character in text.chars() { match character { '"' => self.raw("\\\"", control)?, '\\' => self.raw("\\\\", control)?, '\u{0008}' => self.raw("\\b", control)?, '\u{000c}' => self.raw("\\f", control)?, '\n' => self.raw("\\n", control)?, '\r' => self.raw("\\r", control)?, '\t' => self.raw("\\t", control)?, character if (character as u32) < 0x20 => { use fmt::Write as _; let mut scalar = ScalarText::new(); write!(scalar, "\\u{:04x}", character as u32).map_err(|_| "controlled JSON escape overflow")?; self.raw(scalar.text(), control)?; }, character => { let mut bytes = [0; 4]; self.raw(character.encode_utf8(&mut bytes), control)?; } } control.advance(character.len_utf8())?; } Ok(()) })?;
        self.raw("\"", control)
    }
    fn number(&mut self, number: protocol::value::Number, control: &mut protocol::value::NativeEncodeControl<'_>) -> Result<(), String> {
        use fmt::Write as _; control.checkpoint()?; let mut scalar = ScalarText::new();
        match number { protocol::value::Number::UInt(value) => write!(scalar, "{value}"), protocol::value::Number::Int(value) => write!(scalar, "{value}"), protocol::value::Number::Float(value) => write_float_to(value, &mut scalar) }.map_err(|_| "controlled JSON scalar overflow")?;
        self.raw(scalar.text(), control)?; control.checkpoint()
    }
    fn value(&mut self, value: &DslValue, control: &mut protocol::value::NativeEncodeControl<'_>) -> Result<(), String> {
        control.scoped_depth(MAX_DEPTH as usize + 1, |control| { control.checkpoint()?; match value {
            DslValue::Null => self.raw("null", control), DslValue::Bool(value) => self.raw(if *value { "true" } else { "false" }, control), DslValue::Number(value) => self.number(*value, control), DslValue::String(value) => self.string(value, control),
            DslValue::Array(values) => { self.raw("[", control)?; control.scoped_stage(|control| -> Result<(), String> { control.begin_stage(values.len())?; for (index, value) in values.iter().enumerate() { if index > 0 { self.raw(",", control)?; } self.value(value, control)?; control.step()?; } Ok(()) })?; self.raw("]", control) },
            DslValue::Bytes(values) => { self.raw("[", control)?; control.scoped_stage(|control| -> Result<(), String> { control.begin_stage(values.len())?; for (index, value) in values.iter().enumerate() { if index > 0 { self.raw(",", control)?; } self.number(protocol::value::Number::UInt(u64::from(*value)), control)?; control.step()?; } Ok(()) })?; self.raw("]", control) },
            DslValue::Object(entries) => { self.raw("{", control)?; control.scoped_stage(|control| -> Result<(), String> { control.begin_stage(entries.len())?; for (index, (key, value)) in entries.iter().enumerate() { if index > 0 { self.raw(",", control)?; } self.string(key, control)?; self.raw(":", control)?; self.value(value, control)?; control.step()?; } Ok(()) })?; self.raw("}", control) }
        } })
    }
}

struct ControlledReader<'text, 'control, 'progress> { lexer: Lexer<'text>, control: &'control mut protocol::value::NativeDecodeControl<'progress> }
impl ControlledReader<'_, '_, '_> {
    fn error(&self) -> ValueError { ValueError::new(JsonError::UnexpectedByte { found: self.lexer.peek_byte().unwrap_or(0), offset: self.lexer.pos }.to_string()) }
    fn advance(&mut self, count: usize) -> Result<(), ValueError> { self.lexer.pos += count; self.control.advance(count).map_err(ValueError::new) }
    fn whitespace(&mut self) -> Result<(), ValueError> { while matches!(self.lexer.peek_byte(), Some(b' ' | b'\t' | b'\r' | b'\n')) { self.advance(1)?; } Ok(()) }
    fn reserve<T>(&mut self, values: &mut Vec<T>) -> Result<(), ValueError> {
        if values.len() == values.capacity() {
            let count = values.capacity().max(1).checked_mul(2).ok_or_else(|| ValueError::new("controlled JSON collection overflow"))?;
            let bytes = count.checked_mul(std::mem::size_of::<T>()).filter(|bytes| *bytes <= isize::MAX as usize).ok_or_else(|| ValueError::new("controlled JSON collection overflow"))?;
            self.control.charge(bytes).map_err(ValueError::new)?; values.try_reserve_exact(count - values.len()).map_err(|_| ValueError::new("controlled JSON allocation failed"))?;
        } Ok(())
    }
    fn string(&mut self) -> Result<String, ValueError> {
        self.advance(1)?; let body = self.lexer.pos; let mut length = 0usize;
        loop { let start = self.lexer.pos; let character = json_character(&mut self.lexer).map_err(|error| ValueError::new(error.to_string()))?; self.control.advance(self.lexer.pos - start).map_err(ValueError::new)?; let Some(character) = character else { break }; length = length.checked_add(character.len_utf8()).ok_or_else(|| ValueError::new("controlled JSON string overflow"))?; }
        let input = self.lexer.input; let end = self.lexer.pos; self.control.charge(length).map_err(ValueError::new)?;
        self.control.scoped_stage(|control| {
            control.begin_stage(end - body).map_err(ValueError::new)?; let mut output = String::new(); output.try_reserve_exact(length).map_err(|_| ValueError::new("controlled JSON text allocation failed"))?;
            let mut decoder = Lexer { input, pos: body };
            loop { let start = decoder.pos; let character = json_character(&mut decoder).map_err(|error| ValueError::new(error.to_string()))?; control.advance(decoder.pos - start).map_err(ValueError::new)?; let Some(character) = character else { break }; output.push(character); }
            if output.len() != length || decoder.pos != end { return Err(ValueError::new("controlled JSON string changed after admission")); } Ok(output)
        })
    }
    fn value(&mut self) -> Result<DslValue, ValueError> {
        self.control.scoped_depth(MAX_DEPTH as usize + 1, |control| { let mut reader = ControlledReader { lexer: Lexer { input: self.lexer.input, pos: self.lexer.pos }, control }; let result = reader.value_inner(); self.lexer.pos = reader.lexer.pos; result })
    }
    fn value_inner(&mut self) -> Result<DslValue, ValueError> {
        self.whitespace()?; self.control.checkpoint().map_err(ValueError::new)?;
        match self.lexer.peek_byte() {
            Some(b'"') => self.string().map(DslValue::String),
            Some(b't' | b'f' | b'n') => { let (text, value) = match self.lexer.peek_byte().unwrap() { b't' => ("true", DslValue::Bool(true)), b'f' => ("false", DslValue::Bool(false)), _ => ("null", DslValue::Null) }; if !self.lexer.input[self.lexer.pos..].starts_with(text) { return Err(self.error()); } self.advance(text.len())?; Ok(value) }
            Some(b'-' | b'0'..=b'9') => {
                let start = self.lexer.pos; while matches!(self.lexer.peek_byte(), Some(b'-' | b'+' | b'.' | b'e' | b'E' | b'0'..=b'9')) { self.advance(1)?; }
                let mut number = Lexer::new(&self.lexer.input[start..self.lexer.pos]); let Token::Number(value) = number.read_number().map_err(|error| ValueError::new(error.to_string()))? else { unreachable!() }; if number.pos != number.input.len() { return Err(ValueError::new(JsonError::InvalidNumber(start).to_string())); }
                Ok(DslValue::Number(match value { Number::UInt(value) => protocol::value::Number::UInt(value), Number::Int(value) => protocol::value::Number::Int(value), Number::Float(value) => protocol::value::Number::Float(value) }))
            }
            Some(b'[') => {
                self.advance(1)?; self.whitespace()?; let mut values = Vec::<DslValue>::new().guard_decoded();
                if self.lexer.peek_byte() == Some(b']') { self.advance(1)?; return Ok(DslValue::Array(values.take())); }
                loop { let value = self.value()?.guard_decoded(); self.reserve(values.get_mut())?; values.get_mut().push(value.take()); self.whitespace()?; match self.lexer.peek_byte() { Some(b',') => self.advance(1)?, Some(b']') => { self.advance(1)?; return Ok(DslValue::Array(values.take())); }, _ => return Err(self.error()) } }
            }
            Some(b'{') => {
                self.advance(1)?; self.whitespace()?; let mut entries = protocol::value::DecodedValue::new(Vec::new(), |entries: Vec<(String, DslValue)>| { for (_, value) in entries { FromValue::retire_decoded(value); } });
                if self.lexer.peek_byte() == Some(b'}') { self.advance(1)?; return Ok(DslValue::Object(entries.take())); }
                loop {
                    self.whitespace()?; if self.lexer.peek_byte() != Some(b'"') { return Err(self.error()); } let key = self.string()?; self.whitespace()?; if self.lexer.peek_byte() != Some(b':') { return Err(self.error()); } self.advance(1)?; let value = self.value()?.guard_decoded();
                    let duplicate = self.control.scoped_stage(|control| -> Result<Option<usize>, ValueError> { control.begin_stage(entries.get().len()).map_err(ValueError::new)?; for (index, (name, _)) in entries.get().iter().enumerate() { let equal = controlled_key_equal(name, &key, control)?; control.step().map_err(ValueError::new)?; if equal { return Ok(Some(index)); } } Ok(None) })?;
                    if let Some(index) = duplicate { FromValue::retire_decoded(std::mem::replace(&mut entries.get_mut()[index].1, value.take())); } else { self.reserve(entries.get_mut())?; entries.get_mut().push((key, value.take())); }
                    self.whitespace()?; match self.lexer.peek_byte() { Some(b',') => self.advance(1)?, Some(b'}') => { self.advance(1)?; return Ok(DslValue::Object(entries.take())); }, _ => return Err(self.error()) }
                }
            }
            _ => Err(self.error())
        }
    }
}

fn controlled_key_equal(left: &str, right: &str, control: &mut protocol::value::NativeDecodeControl<'_>) -> Result<bool, ValueError> {
    if left.len() != right.len() { return Ok(false); } control.scoped_stage(|control| { control.begin_stage(left.len()).map_err(ValueError::new)?; let mut position = 0; while position < left.len() { let end = position.saturating_add(65536).min(left.len()); let equal = left.as_bytes()[position..end] == right.as_bytes()[position..end]; control.advance(end - position).map_err(ValueError::new)?; if !equal { return Ok(false); } position = end; } Ok(true) })
}

fn json_character(lexer: &mut Lexer<'_>) -> Result<Option<char>, JsonError> {
    let character = lexer.input[lexer.pos..].chars().next().ok_or(JsonError::UnexpectedEof)?;
    match character {
        '"' => { lexer.pos += 1; Ok(None) },
        '\\' => {
            let start = lexer.pos; lexer.pos += 1; let escaped = lexer.input[lexer.pos..].chars().next().ok_or(JsonError::UnexpectedEof)?; lexer.pos += escaped.len_utf8();
            let character = match escaped { '"' => '"', '\\' => '\\', '/' => '/', 'b' => '\u{0008}', 'f' => '\u{000c}', 'n' => '\n', 'r' => '\r', 't' => '\t', 'u' => { let unit = lexer.read_hex4(start)?; if (0xd800..=0xdbff).contains(&unit) { if lexer.peek_byte() != Some(b'\\') { return Err(JsonError::UnpairedSurrogate(start)); } lexer.pos += 1; if lexer.peek_byte() != Some(b'u') { return Err(JsonError::UnpairedSurrogate(start)); } lexer.pos += 1; let low = lexer.read_hex4(start)?; if !(0xdc00..=0xdfff).contains(&low) { return Err(JsonError::UnpairedSurrogate(start)); } char::from_u32(0x10000 + ((unit - 0xd800) << 10) + low - 0xdc00).ok_or(JsonError::UnpairedSurrogate(start))? } else if (0xdc00..=0xdfff).contains(&unit) { return Err(JsonError::UnpairedSurrogate(start)); } else { char::from_u32(unit).ok_or(JsonError::InvalidUnicodeEscape(start))? } }, _ => return Err(JsonError::InvalidEscape(start)) }; Ok(Some(character))
        }
        control if (control as u32) < 0x20 => Err(JsonError::ControlCharacterInString { byte: control as u8, offset: lexer.pos }),
        character => { lexer.pos += character.len_utf8(); Ok(Some(character)) }
    }
}
//#endregion 🔖️ToFromValueBridge

//#region 🔖️Macro
/// 🧩️ `serde_json::json!` replacement — an object/array literal builder over [`Value`], expanded
/// via the standard TT-muncher recursion (see `json_object_internal!`/`json_array_internal!`,
/// `#[doc(hidden)]`, exported only so this macro's own expansion can call them from any crate).
/// Object keys are string literals (`"key": value`); leaf expressions are borrowed and encoded
/// through [`ToValue`], preserving access to records and fields after constructing the JSON tree.
#[macro_export]
macro_rules! json {
    (null) => { $crate::json::Value::Null };
    (true) => { $crate::json::Value::Bool(true) };
    (false) => { $crate::json::Value::Bool(false) };
    ([]) => { $crate::json::Value::Array(::std::vec::Vec::new()) };
    ([ $($tt:tt)+ ]) => {
        $crate::json::Value::Array($crate::json_array_internal!(@collect [] $($tt)+))
    };
    ({}) => { $crate::json::Value::Object($crate::json::Object::new()) };
    ({ $($tt:tt)+ }) => {
        $crate::json::Value::Object({
            let mut __object = $crate::json::Object::new();
            $crate::json_object_internal!(__object $($tt)+);
            __object
        })
    };
    ($other:expr) => {{
        use $crate::json::ToValue as _;
        $crate::json::from_dsl_value(&(&$other).to_value())
    }};
}

#[macro_export]
#[doc(hidden)]
macro_rules! json_array_internal {
    (@collect [$($elems:expr,)*]) => {
        ::std::vec![$($elems),*]
    };
    (@collect [$($elems:expr,)*] null $(, $($rest:tt)*)?) => {
        $crate::json_array_internal!(@collect [$($elems,)* $crate::json!(null),] $($($rest)*)?)
    };
    (@collect [$($elems:expr,)*] [$($array:tt)*] $(, $($rest:tt)*)?) => {
        $crate::json_array_internal!(@collect [$($elems,)* $crate::json!([$($array)*]),] $($($rest)*)?)
    };
    (@collect [$($elems:expr,)*] {$($object:tt)*} $(, $($rest:tt)*)?) => {
        $crate::json_array_internal!(@collect [$($elems,)* $crate::json!({$($object)*}),] $($($rest)*)?)
    };
    (@collect [$($elems:expr,)*] $next:expr $(, $($rest:tt)*)?) => {
        $crate::json_array_internal!(@collect [$($elems,)* $crate::json!($next),] $($($rest)*)?)
    };
}

#[macro_export]
#[doc(hidden)]
macro_rules! json_object_internal {
    ($object:ident) => {};
    ($object:ident $key:literal : null $(, $($rest:tt)*)?) => {
        $object.insert($key, $crate::json!(null));
        $crate::json_object_internal!($object $($($rest)*)?);
    };
    ($object:ident $key:literal : [$($array:tt)*] $(, $($rest:tt)*)?) => {
        $object.insert($key, $crate::json!([$($array)*]));
        $crate::json_object_internal!($object $($($rest)*)?);
    };
    ($object:ident $key:literal : {$($inner:tt)*} $(, $($rest:tt)*)?) => {
        $object.insert($key, $crate::json!({$($inner)*}));
        $crate::json_object_internal!($object $($($rest)*)?);
    };
    ($object:ident $key:literal : $value:expr $(, $($rest:tt)*)?) => {
        $object.insert($key, $crate::json!($value));
        $crate::json_object_internal!($object $($($rest)*)?);
    };
}
//#endregion 🔖️Macro

