#[test]
fn value_eq_ignoring_object_order_is_order_insensitive_but_still_structural() {
    let a = crate::json!({"x": 1, "y": [1, 2, {"p": true, "q": "s"}]});
    let b = crate::json!({"y": [1, 2, {"q": "s", "p": true}], "x": 1});
