/** 🧮️ Checks the literal strict-wire corpus with an independent BigInt/UTF-8 accounting oracle. */
export async function proveWireValueMaterializationFixture(repoRoot: string): Promise<void> {
  const assert: typeof import("node:assert/strict") = (await import("node:assert/strict")).default;
  const Ajv = (await import("ajv")).default;
  const equal = (await import("fast-deep-equal")).default;
  const root = join(repoRoot, "🧰️framework/🛍️products/💻️os/🔨️modules/🎒️pack/🌱️value");
  const fixture = JSON.parse(readFileSync(join(root, "🧫️fixtures/🧮️wire-materialization/🔣️.json"), "utf8"));
  const contract = JSON.parse(readFileSync(join(root, "🧬️schema/🔣️.json"), "utf8"));
  const ajv = new Ajv({ strict: true, allErrors: true });
  ajv.addSchema(contract);
  const validate = ajv.getSchema(`${contract.$id}#/$defs/WireValueMaterialization`)!;
  assert(validate(fixture), JSON.stringify(validate.errors));
  assert.deepEqual(fixture.cases.map((row: { id: string }) => row.id), contract.$defs.WireValueMaterializationCase.properties.id.enum);
  assert.deepEqual(fixture.bridge, { fieldId: 1, rootTag: "11", exact: true });
  const { decodePackValue, packValueToExactJson } = await import("../../../🟦️.ts");
  for (const row of fixture.cases) {
    const bytes = Buffer.from(row.rawHex, "hex");
    const limits = row.limits;
    let offset = 0, used = 0n;
    const refuse = (outcome: "limit" | "malformed"): never => { throw { outcome }; };
    const charge = (amount: bigint): void => {
      used += amount;
      if (used > BigInt(limits.maxTotalAlloc) || used > 18_446_744_073_709_551_615n) refuse("limit");
    };
    const byte = (): number => {
      if (offset >= bytes.length) return refuse("malformed");
      return bytes[offset++];
    };
    const integer = (): bigint => {
      let value = 0n;
      for (let index = 0; index < 10; index++) {
        const next = byte();
        if (index === 9 && (next & 0xfe) !== 0) return refuse("malformed");
        value |= BigInt(next & 0x7f) << BigInt(index * 7);
        if ((next & 0x80) === 0) return value;
      }
      return refuse("malformed");
    };
    const text = (): string => {
      const length = integer();
      if (length > BigInt(limits.maxSegmentLen)) return refuse("limit");
      if (length > BigInt(bytes.length - offset)) return refuse("malformed");
      charge(length);
      const start = offset;
      offset += Number(length);
      try { return new TextDecoder("utf-8", { fatal: true }).decode(bytes.subarray(start, offset)); }
      catch { return refuse("malformed"); }
    };
    const symbols: string[] = [];
    const string = (tag: number): string => {
      if (tag === 7) return text();
      if (tag !== 6) return refuse("malformed");
      const index = integer();
      if (index >= BigInt(symbols.length)) return refuse("malformed");
      const value = symbols[Number(index)];
      charge(BigInt(Buffer.byteLength(value, "utf8")));
      return value;
    };
    const value = (depth: number): unknown => {
      if (depth > limits.maxDepth) return refuse("limit");
      const tag = byte();
      if (tag === 0x12) return null;
      if (tag === 1 || tag === 2) return tag === 2;
      if (tag === 3) { const raw = integer(); return Number((raw >> 1n) ^ -(raw & 1n)); }
      if (tag === 4) return Number(integer());
      if (tag === 5) {
        if (bytes.length - offset < 8) return refuse("malformed");
        const number = new DataView(bytes.buffer, bytes.byteOffset + offset, 8).getFloat64(0, true);
        offset += 8;
        return number;
      }
      if (tag === 6 || tag === 7) return string(tag);
      if (tag !== 0x0c && tag !== 0x10) return refuse("malformed");
      const count = integer();
      if (count > BigInt(limits.maxItems)) return refuse("limit");
      charge(count * 64n);
      const values: unknown[] = [], entries: [string, unknown][] = [];
      for (let index = 0n; index < count; index++) {
        if (tag === 0x0c) values.push(value(depth + 1));
        else entries.push([string(byte()), value(depth + 1)]);
      }
      return tag === 0x0c ? values : Object.fromEntries(entries);
    };
    let actual: { outcome: string; value?: unknown };
    try {
      if (bytes.length > limits.maxFileLen) refuse("limit");
      const count = integer();
      if (count > BigInt(limits.maxSymbols)) refuse("limit");
      charge(count * 32n);
      for (let index = 0n; index < count; index++) symbols.push(text());
      if (integer() !== 1n || integer() !== BigInt(fixture.bridge.fieldId) || byte() !== 0x11) refuse("malformed");
      const decoded = value(0);
      if (offset !== bytes.length) refuse("malformed");
      actual = { outcome: "accepted", value: decoded };
    } catch (error) {
      if (!error || typeof error !== "object" || !("outcome" in error)) throw error;
      actual = error as { outcome: string };
    }
    assert.equal(actual.outcome, row.expect.outcome, row.id);
    if (actual.outcome === "accepted") {
      assert(equal(actual.value, row.expect.value), row.id + " independent JSON output");
      assert(equal(packValueToExactJson(decodePackValue(bytes)), row.expect.value), row.id + " first-party Pack output");
      assert.deepEqual(JSON.parse(JSON.stringify(actual.value)), row.expect.value, row.id + " JSON oracle");
    }
  }
  const owner = readFileSync(join(root, "🦀️.rs"), "utf8");
  const store = readFileSync(join(repoRoot, "🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/🦀️.rs"), "utf8");
  for (const marker of ["pub fn decode_value_record_body_exact(", "wire value materialization exceeds max_total_alloc", "fn decode_inline_symbols(", "fn value_slots<T>(", "copy_decoded_string(value, ctx.materialization.as_ref())"]) assert(owner.includes(marker), marker);
  assert(store.includes("decode_wire_value_with_options(bytes, &PackDecodeOptions::default())"));
  console.log(`wire-value materialization: AJV=1 BigInt-accounting=1 JSON+deep-equal+Pack=1 cases=${fixture.cases.length}; native decoder behavior remains a separate exact law`);
}

//! 🛫️ Literal Pack fields with borrowed symbol discovery and controlled physical emission.
use super::*;
use protocol::value::native_encoding::NativeEncodeControl;
use crate::os_dsl::NativeSchemaControl;
use std::{cmp::Ordering,mem::size_of};

fn push<T>(values:&mut Vec<T>,value:T,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if values.len()==values.capacity(){let capacity=if values.capacity()==0{1}else{values.capacity().checked_mul(2).ok_or("Pack output frontier capacity overflow")?};control.charge(capacity.checked_mul(size_of::<T>()).ok_or("Pack output frontier size overflow")?)?;control.checkpoint()?;values.try_reserve_exact(capacity-values.len()).map_err(|_|"Pack output frontier allocation")?;}values.push(value);Ok(())}
fn nested(shape:Option<&Shape>,control:&mut NativeEncodeControl<'_>)->Result<Option<RecordSpec>,String>{match shape{Some(Shape::Record(producer))=>producer.encode(control).map(Some),_=>Ok(None)}}

#[derive(Clone,Copy)]
struct Symbol<'a>{text:&'a str,forced:bool}
struct Symbols<'a>{entries:Vec<Symbol<'a>>}
impl<'a> Symbols<'a>{
    fn note(&mut self,text:&'a str,forced:bool,control:&mut NativeEncodeControl<'_>)->Result<(),String>{push(&mut self.entries,Symbol{text,forced},control)}
    fn record(&mut self,spec:Option<&RecordSpec>,record:&'a RecordValue,depth:u16,maximum:u16,control:&mut NativeEncodeControl<'_>)->Result<(),String>{
        if depth>maximum.min(64){return Err("Pack symbol discovery depth exceeds limit".into())}control.scoped_stage(|control|{control.begin_stage(record.fields.len())?;for(id,value)in &record.fields{let shape=spec.and_then(|spec|spec.fields.iter().find(|field|field.id==*id)).map(|field|&field.shape);self.value(shape,value,depth+1,maximum,control)?;control.step()?;}Ok(())})
    }
    fn value(&mut self,shape:Option<&Shape>,value:&'a FieldValue,depth:u16,maximum:u16,control:&mut NativeEncodeControl<'_>)->Result<(),String>{
        if depth>maximum.min(64){return Err("Pack symbol discovery depth exceeds limit".into())}control.scoped_stage(|control|{control.begin_stage(0)?;control.step()?;match value{
            FieldValue::Text(text)=>self.note(text,false,control)?,
            FieldValue::Tuple(items)=>{control.begin_stage(items.len())?;for item in items{self.value(elem_shape_of(shape),item,depth+1,maximum,control)?;control.step()?;}},
            FieldValue::List(items)=>{let table=table_spec_of(shape).map(|producer|producer.encode(control)).transpose()?;control.begin_stage(items.len())?;for item in items{if let(Some(spec),FieldValue::Record(row))=(&table,item){for field in &spec.fields{if let Some(value)=row.fields.get(&field.id){if matches!(field.shape,Shape::Text){if let FieldValue::Text(text)=value{self.note(text,true,control)?;}}else{self.value(Some(&field.shape),value,depth+1,maximum,control)?;}}}}else{self.value(elem_shape_of(shape),item,depth+1,maximum,control)?;}control.step()?;}},
            FieldValue::Record(record)=>{let spec=nested(shape,control)?;self.record(spec.as_ref(),record,depth+1,maximum,control)?;},
            FieldValue::Block(value)=>self.value(block_inner_shape(shape),value,depth+1,maximum,control)?,
            FieldValue::Statements(items)=>{control.begin_stage(items.len())?;for(keyword,record)in items{self.note(keyword,true,control)?;let spec=statements_variants(shape).and_then(|variants|variants.iter().find(|(key,_)|key==keyword)).map(|(_,producer)|producer.encode(control)).transpose()?;self.record(spec.as_ref(),record,depth+1,maximum,control)?;control.step()?;}},
            FieldValue::Map(items)=>{control.begin_stage(items.len())?;for(key,value)in items{self.note(key,false,control)?;self.value(map_inner_shape(shape),value,depth+1,maximum,control)?;control.step()?;}},
            FieldValue::Value(value)=>self.dynamic(value,depth+1,maximum,control)?,
            FieldValue::Wire(wire)=>{self.node(&wire.from,control)?;if let Some((_,node))=&wire.edge{self.node(node,control)?;}self.dynamic(&wire.properties,depth+1,maximum,control)?;},
            FieldValue::Absent|FieldValue::Bool(_)|FieldValue::Int(_)|FieldValue::UInt(_)|FieldValue::Float(_)|FieldValue::Bytes64(_)|FieldValue::Enum(_)|FieldValue::Expr(_)=>{},
        }Ok(())})
    }
    fn node(&mut self,node:&'a WireNode,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.note(&node.id,false,control)?;if let Some(text)=&node.kind{self.note(text,false,control)?;}if let Some(text)=&node.port{self.note(text,false,control)?;}Ok(())}
    fn dynamic(&mut self,value:&'a DslValue,depth:u16,maximum:u16,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if depth>maximum.min(64){return Err("Pack dynamic symbol depth exceeds limit".into())}control.scoped_stage(|control|{control.begin_stage(0)?;control.step()?;match value{DslValue::String(text)=>self.note(text,false,control)?,DslValue::Array(items)=>{control.begin_stage(items.len())?;for item in items{self.dynamic(item,depth+1,maximum,control)?;control.step()?;}},DslValue::Object(items)=>{control.begin_stage(items.len())?;for(_,item)in items{self.dynamic(item,depth+1,maximum,control)?;control.step()?;}},DslValue::Null|DslValue::Bool(_)|DslValue::Number(_)|DslValue::Bytes(_)=>{}}Ok(())})}
    fn finish(&mut self,control:&mut NativeEncodeControl<'_>)->Result<(),String>{
        controlled_schema::sort(&mut self.entries,|a,b,control|controlled_schema::compare_text(a.text,b.text,control),control)?;
        control.scoped_stage(|control|{control.begin_stage(self.entries.len())?;let mut start=0;let mut output=0;while start<self.entries.len(){let text=self.entries[start].text;let mut end=start+1;let mut forced=self.entries[start].forced;control.step()?;while end<self.entries.len()&&controlled_schema::compare_text(text,self.entries[end].text,control)?==Ordering::Equal{forced|=self.entries[end].forced;end+=1;control.step()?;}if forced||text.len()<=128||end-start>=2{self.entries[output]=Symbol{text,forced};output+=1;}start=end;}self.entries.truncate(output);Ok(())})
    }
    fn index(&self,text:&str,control:&mut NativeEncodeControl<'_>)->Result<Option<u64>,String>{let mut low=0;let mut high=self.entries.len();while low<high{let middle=low+(high-low)/2;match controlled_schema::compare_text(self.entries[middle].text,text,control)?{Ordering::Less=>low=middle+1,Ordering::Greater=>high=middle,Ordering::Equal=>return Ok(Some(middle as u64))}}Ok(None)}
}

fn table_value(row:&FieldValue,id:u16)->Option<&FieldValue>{match row{FieldValue::Record(record)=>record.fields.get(&id).filter(|value|!matches!(value,FieldValue::Absent)),_=>None}}

struct Output{bytes:Option<Vec<u8>>,length:usize}
impl Output{
    fn measure()->Self{Self{bytes:None,length:0}}
    fn allocated(length:usize,control:&mut NativeEncodeControl<'_>)->Result<Self,String>{Ok(Self{bytes:Some(control.allocate_vec(length)?),length:0})}
    fn bytes(&mut self,bytes:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.length=self.length.checked_add(bytes.len()).ok_or("Pack output length overflow")?;if let Some(output)=&mut self.bytes{if bytes.len()>output.capacity()-output.len(){return Err("Pack output exceeded admitted length".into())}control.scoped_stage(|control| -> ::core::result::Result<(),String> {control.begin_stage(bytes.len())?;for fragment in bytes.chunks(65536){output.extend_from_slice(fragment);control.advance(fragment.len())?;}Ok::<_,String>(())})?;}Ok(())}
    fn byte(&mut self,byte:u8,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.bytes(&[byte],control)}
    fn varint(&mut self,mut value:u64,control:&mut NativeEncodeControl<'_>)->Result<(),String>{let mut bytes=[0;10];let mut length=0;loop{bytes[length]=(value as u8)&127;value>>=7;if value!=0{bytes[length]|=128;}length+=1;if value==0{break;}}self.bytes(&bytes[..length],control)}
    fn signed(&mut self,value:i64,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.varint(((value as u64)<<1)^((value>>63)as u64),control)}
}

struct Encoder<'a,'b,'c,'d>{symbols:&'a Symbols<'b>,options:&'a EncodeOptions,control:&'c mut NativeEncodeControl<'d>,writer:Option<&'c mut crate::os_pack::format::ControlledPackWriter>,chunking:bool,next_chunk:u32}
impl Encoder<'_,'_,'_,'_>{
    fn text(&mut self,text:&str,inline:bool,output:&mut Output)->Result<(),String>{if !inline{if let Some(index)=self.symbols.index(text,self.control)?{output.byte(TAG_STR,self.control)?;return output.varint(index,self.control)}}output.byte(TAG_STR_INLINE,self.control)?;output.varint(text.len()as u64,self.control)?;output.bytes(text.as_bytes(),self.control)}
    fn forced(&mut self,text:&str,output:&mut Output)->Result<(),String>{let index=self.symbols.index(text,self.control)?.ok_or("Pack forced symbol missing")?;output.varint(index,self.control)}
    fn fields(&mut self,spec:Option<&RecordSpec>,record:&RecordValue,depth:u16,output:&mut Output)->Result<(),String>{
