//#endregion 🔖️Value

//#region 🔖️Encode
/// 🚪️ Encodes `record` (validated against `spec`) into a complete `.spk` pack file's
/// bytes. Thin forward onto `crate::value::encode_document` — see there for the canonical-mode
/// rules and the purity law (byte-identical output for a given `(spec, record)` regardless of
/// `HashMap` iteration order).
pub fn encode_document(spec: &crate::os_dsl::schema::RecordSpec, record: &crate::os_dsl::schema::RecordValue, options: &EncodeOptions) -> Result<Vec<u8>, PackError> {
    crate::value::encode_document(spec, record, options)
}

/// 🛫️ Emits declared document fields under cumulative caller-owned native output admission.
pub fn encode_document_controlled(spec:&crate::os_dsl::RecordSpec,record:&crate::os_dsl::RecordValue,options:&EncodeOptions,control:&mut protocol::value::native_encoding::NativeEncodeControl<'_>)->Result<Vec<u8>,PackError>{crate::value::encode_document_controlled(spec,record,options,control)}

/// 🚪️ Decodes a complete `.spk` pack file's bytes back into a `RecordValue`, plus a
/// `DecodeReport` describing anything the caller's `spec` didn't account for. Thin forward onto
/// `crate::value::decode_document`.
pub fn decode_document(bytes: &[u8], spec: &crate::os_dsl::schema::RecordSpec, options: &DecodeOptions) -> Result<(crate::os_dsl::schema::RecordValue, DecodeReport), PackError> {
    crate::value::decode_document(bytes, spec, options)
}
/// 🛬️ Reads a complete Pack file through caller-controlled physical and primitive decoding.
pub fn decode_document_controlled(bytes:&[u8],spec:&crate::os_dsl::RecordSpec,options:&DecodeOptions,control:&mut protocol::value::native_decoding::NativeDecodeControl<'_>)->Result<(crate::os_dsl::RecordValue,DecodeReport),PackError>{
    crate::value::decode_document_controlled(bytes,spec,options,control)
}

/// 🎯️ Encodes one record as a container-less binary body (symbol table + fields, no
/// header/manifest/footer, no chunking) — the payload form for operation/command records. Thin
/// forward onto `crate::value::encode_record_body`; same determinism law as `encode_document`.
pub fn encode_record_body(spec: &crate::os_dsl::schema::RecordSpec, record: &crate::os_dsl::schema::RecordValue, options: &EncodeOptions) -> Result<Vec<u8>, PackError> {
    crate::value::encode_record_body(spec, record, options)
}

/// 🛫️ Emits a terminal record through the same control as its typed field projection.
pub fn encode_record_body_controlled(spec:&crate::os_dsl::RecordSpec,record:&crate::os_dsl::RecordValue,options:&EncodeOptions,control:&mut protocol::value::native_encoding::NativeEncodeControl<'_>)->Result<Vec<u8>,PackError>{crate::value::encode_record_body_controlled(spec,record,options,control)}

/// 🎯️ Decodes an `encode_record_body` payload back into a `RecordValue` plus its
/// `DecodeReport`. Thin forward onto `crate::value::decode_record_body`.
pub fn decode_record_body(bytes: &[u8], spec: &crate::os_dsl::schema::RecordSpec, options: &DecodeOptions) -> Result<(crate::os_dsl::schema::RecordValue, DecodeReport), PackError> {
    crate::value::decode_record_body(bytes, spec, options)
}

/// 🛂️ Admits one terminal schema-owned record without unknown fields or byte suffixes.
pub fn decode_record_body_exact(bytes: &[u8], spec: &crate::os_dsl::schema::RecordSpec, options: &DecodeOptions) -> Result<crate::os_dsl::schema::RecordValue, PackError> {
    crate::value::decode_record_body_exact(bytes, spec, options)
}

/// 🛬️ Parses a terminal record with the same caller control used for typed construction.
pub fn decode_record_body_exact_controlled(bytes:&[u8],spec:&crate::os_dsl::RecordSpec,options:&DecodeOptions,control:&mut protocol::value::native_decoding::NativeDecodeControl<'_>)->Result<crate::os_dsl::RecordValue,PackError>{
    crate::value::decode_record_body_exact_controlled(bytes,spec,options,control)
}

/// #⃣ Reads only the trailing footer of an encoded pack file and returns its stored
/// `content_hash` — no header/manifest/document decode needed. Thin forward onto
/// `crate::format::read_footer_only`.
pub fn content_hash(bytes: &[u8]) -> Result<ContentHash, PackError> {
    crate::os_io::resolve_ready(read_footer_only(&bytes)).map(|footer| footer.content_hash)
