#!/usr/bin/env bun
/** 🧬️ Independent language-neutral mutation payload placement oracle. */
import Ajv from "ajv";
import { strict as assert } from "node:assert";
import picomatch from "picomatch";
import { mutationDomainOwnersProblems, mutationOwnerIdentity, loadCatalogTaxonomy } from "../../../../../../🦑️repo/🔨️modules/📚️library/🔍️discovery/🟦️.ts";

type LayoutCase = { readonly name: string; readonly accepted: boolean; readonly relativeSource?: string };

const fixture = await Bun.file(new URL("../../🧫️fixtures/🛂️mutation-source-authority/🔣️.json", import.meta.url)).json();
const document = await Bun.file(new URL("../../🧬️schema/🔣️.json", import.meta.url)).json();
const ajv = new Ajv({ strict: true, allErrors: true });
ajv.addSchema(document);
const validate = ajv.getSchema(`${document.$id}#/$defs/MutationSourceAuthorityV1`)!;
assert(validate(fixture), JSON.stringify(validate.errors));

const acceptsLayout = (source: string): boolean => {
  const segments = source.split("/");
  const collection = segments.indexOf("🧬️mutations");
  if (collection < 0 || segments.at(-1) !== "🦀️.rs") return false;
  const tail = segments.slice(collection + 1);
  return tail.length === 2 || tail.length === 3 && tail[1] === "🦠️mutation";
};

const layoutCases = (fixture.cases as LayoutCase[]).filter((item) => item.relativeSource !== undefined);
for (const item of layoutCases) assert.equal(acceptsLayout(item.relativeSource!), item.accepted, item.name);
const hostile = [
  { ...fixture, extra: true },
  { ...fixture, cases: [...fixture.cases, { name: "invalid", accepted: true, relativeSource: "" }] },
];
for (const item of hostile) assert(!validate(item));
assert(!acceptsLayout("domain/🧬️mutations/🆕️insert-page/unknown/🦀️.rs"));
assert(!acceptsLayout("domain/🧬️mutations/🆕️insert-page/🦠️mutation/nested/🦀️.rs"));

const domainFixture = await Bun.file(new URL("../../../../../../../🔨️modules/📡️replication/🎮️mutation/🧫️fixtures/🛂️mutation-source-authority/🧭️domains.json", import.meta.url)).json();
const domainSchema = await Bun.file(new URL("../../../../../../../🔨️modules/📡️replication/🎮️mutation/🧬️schema/🛂️mutation-source-authority/🧭️domains.json", import.meta.url)).json();
const validateDomains = ajv.compile(domainSchema);
assert(validateDomains(domainFixture), JSON.stringify(validateDomains.errors));
const taxonomy = { ...loadCatalogTaxonomy(), mutationDomainOwners: { [domainFixture.mutationRoot]: domainFixture.domains } };
assert.deepEqual(mutationDomainOwnersProblems(taxonomy.mutationDomainOwners), []);
const explicitOwners = Object.entries(domainFixture.domains).flatMap(([domain, operations]) => Object.entries(operations as Record<string, string>).map(([operation, identity]) => ({ owner: `${domain}/${operation}`, identity })));
for (const vector of domainFixture.cases) {
  const sourceAllowed = vector.source === "🦀️.rs" || vector.source === "🦠️mutation/🦀️.rs";
  const independent = !vector.fault && sourceAllowed && explicitOwners.some((item) => picomatch(item.owner, { literalBrackets: true })(vector.owner) && item.identity === vector.semanticKind);
  const subject = !vector.fault && sourceAllowed && mutationOwnerIdentity(domainFixture.mutationRoot, vector.owner, taxonomy) === vector.semanticKind;
  assert.equal(independent, vector.accepted, vector.name);
  assert.equal(subject, independent, vector.name);
}

//! 🧪️ Independent `syn` facts for the base mutation declaration contract.

use serde::{Deserialize, Serialize};
use syn::{Item, TraitItem};

#[derive(Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
struct MutationTraitFacts {
    descriptors_has_initializer: bool,
    descriptor_has_default_body: bool,
    sentinel_present: bool,
}

#[derive(Deserialize)]
struct NeutralFacts {
    cases: Vec<NeutralCase>,
}

#[derive(Deserialize)]
struct NeutralCase {
    id: String,
    subject: String,
    category: String,
    facts: MutationTraitFacts,
}

fn mutation_trait_facts(source: &str) -> MutationTraitFacts {
    let file = syn::parse_file(source).expect("actual mutation source must parse");
    let mutations: Vec<_> = file.items.iter().filter_map(|item| match item {
        Item::Trait(item) if matches!(&item.vis, syn::Visibility::Public(_)) && item.ident == "Mutation" => Some(item),
        _ => None,
    }).collect();
    assert_eq!(mutations.len(), 1, "actual source must contain exactly one public Mutation trait");
    let mutation = mutations[0];
    let descriptors: Vec<_> = mutation.items.iter().filter_map(|item| match item {
        TraitItem::Const(item) if item.ident == "DESCRIPTORS" => Some(item),
        _ => None,
    }).collect();
    assert_eq!(descriptors.len(), 1, "Mutation must contain exactly one DESCRIPTORS associated constant");
    let descriptors_has_initializer = descriptors[0].default.is_some();
    let descriptor: Vec<_> = mutation.items.iter().filter_map(|item| match item {
        TraitItem::Fn(item) if item.sig.ident == "descriptor" => Some(item),
        _ => None,
    }).collect();
    assert_eq!(descriptor.len(), 1, "Mutation must contain exactly one descriptor associated method");
    let descriptor_has_default_body = descriptor[0].default.is_some();
    let sentinels = file.items.iter().filter(|item| matches!(item, Item::Const(item) if item.ident == "UNDECLARED_MUTATION_LEAF")).count();
    MutationTraitFacts { descriptors_has_initializer, descriptor_has_default_body, sentinel_present: sentinels != 0 }
}

#[test]
fn mutation_trait_matches_adjacent_required_declaration_facts() {
    let neutral: NeutralFacts = serde_json::from_str(include_str!("../../🧫️fixtures/🪪️mandatory-mutation-descriptor/🔣️.json")).expect("adjacent neutral vector must parse");
    let expected = neutral.cases.into_iter().find(|case| case.id == "required-items-accepted").expect("neutral vector must contain required-items-accepted");
    assert_eq!(expected.subject, "mutation-trait-facts");
    assert_eq!(expected.category, "required-associated-items");
    let actual = mutation_trait_facts(include_str!("../../../../../../../🔨️modules/📡️replication/🎮️mutation/🦀️.rs"));
    println!("actual={} expected={}", serde_json::to_string(&actual).expect("actual facts serialize"), serde_json::to_string(&expected.facts).expect("expected facts serialize"));
    assert_eq!(actual, expected.facts);
}

