    assert_eq!(evaluate(&parse_expr_text("max(3, 5)").unwrap(), &env(&[]).await), Ok(5.0));
    assert_eq!(evaluate(&parse_expr_text("abs(0-4)").unwrap(), &env(&[]).await), Ok(4.0));
