#[semio_framework_async_macros::async_test]
async fn round_trip_matrix() {
    let sources = vec!["uls = 1.35 * G + 1.5 * Q -> 210", "check = N-Ed / N-c-Rd -> 0.28", "simple = 5 -> 5"];
