//! 📡️ `dsl_lsp` — LSP 3.17 JSON-RPC subset and in-process [`LanguageSession`] over
//! [`crate::os_dsl::LanguageSpec`] hooks (semantic tokens, completion, canonicalize).

use semio_framework_dsl::CompletionItem;
use semio_framework_dsl::GrammarFile;
use semio_framework_dsl::LanguageSpec;
use semio_framework_dsl::ProtocolFile;
use semio_framework_diagnostic::TextError;
use semio_framework_dsl::TokenClass;
use crate::os_pack::json::{object, Object, Value};

//#region 🔖️Session
/// 🗣️ In-process language host for editor surfaces (writer, playground).
pub struct LanguageSession {
    spec: LanguageSpec,
    text: String,
}

impl LanguageSession {
    pub fn open(spec: LanguageSpec, text: impl Into<String>) -> Self {
        Self { spec, text: text.into() }
    }

    pub fn set_text(&mut self, text: impl Into<String>) {
        self.text = text.into();
    }

    pub fn language_id(&self) -> &'static str {
        self.spec.id
    }

    pub fn semantic_tokens_lsp(&self) -> Value {
        let classified = (self.spec.hooks.classify)(&self.text);
        let mut data: Vec<u32> = Vec::new();
        let mut prev_line = 0u32;
        let mut prev_start = 0u32;
        for (class, span) in classified {
            let line = span.line.saturating_sub(1);
            let start = span.column.saturating_sub(1);
            let len = span.length.max(1);
            let type_index = match class {
                TokenClass::Keyword => 0,
                TokenClass::String => 1,
                TokenClass::Number => 2,
                TokenClass::Operator => 3,
                TokenClass::Ident => 4,
                _ => 5,
            };
            data.push(line.saturating_sub(prev_line));
            data.push(if line == prev_line { start.saturating_sub(prev_start) } else { start });
            data.push(len);
            data.push(type_index);
            data.push(0);
            prev_line = line;
            prev_start = start;
        }
        object([("data".to_string(), Value::Array(data.into_iter().map(Value::from).collect()))])
    }

    pub fn completions_at(&self, offset: usize) -> Vec<CompletionItem> {
        (self.spec.hooks.complete)(&self.text, offset)
    }

    pub fn canonicalize(&self) -> Result<String, TextError> {
        (self.spec.hooks.canonicalize)(&self.text)
    }

    /// 🩺 Text diagnostics from hooks + grammar dialect checks when `grammar` is present.
    pub fn diagnostics(&self) -> Vec<TextError> {
        let mut out = Vec::new();
        if self.spec.is_text_role() {
            if let Err(error) = self.canonicalize() {
                out.push(error);
            }
            if let Err(error) = self.spec.parsed_grammar() {
                out.push(error);
            }
        }
        out
    }

    /// 📡️ Byte-level protocol verification when `protocol` text is present on the spec.
    pub fn verify_protocol_bytes(&self, bytes: &[u8]) -> Result<(), String> {
        self.spec.verify_protocol(bytes)
    }

    /// 📖️ Parsed grammar file for text roles (`None` when unset).
    pub fn grammar_file(&self) -> Result<Option<GrammarFile>, TextError> {
        self.spec.parsed_grammar()
    }

    /// 📡️ Parsed protocol file for binary verification (`None` when unset).
    pub fn protocol_file(&self) -> Result<Option<ProtocolFile>, TextError> {
        self.spec.parsed_protocol()
    }
}
//#endregion 🔖️Session

//#region 🔖️JsonRpc
/// 📨 Handles one LSP JSON-RPC request string; returns optional response JSON text.
pub fn handle_json_rpc(line: &str, session: &LanguageSession) -> Option<String> {
    let msg: Value = crate::os_pack::json::parse(line).ok()?;
    let id = msg.get("id").cloned();
    let method = msg.get("method")?.as_str()?;
    let result = match method {
        "initialize" => object([("capabilities".to_string(), object([("semanticTokensProvider".to_string(), object([("full".to_string(), Value::from(true))]))]))]),
        "semanticTokens/full" => session.semantic_tokens_lsp(),
        "shutdown" => Value::Null,
        _ => Value::Object(Object::new()),
    };
    id.map(|id| {
        let mut response = Object::new();
        response.insert("jsonrpc", Value::from("2.0"));
        response.insert("id", id);
        response.insert("result", result);
        crate::os_pack::json::to_string(&Value::Object(response))
    })
}
//#endregion 🔖️JsonRpc

//! 🏷️ The record-tag scanner agrees with the protocol dialect parser, and tagged ops carry exactly the declared tag.
use super::*;

const PROTOCOL: &str = "dialect protocol\nprotocol test.mutations\nversion 1\nschema test.op\nstart record\nframing record\n\n# a comment naming record ghost tag=9 is not a record\nheader fixed 2\nfield format u8\nfield tag u8\nrecord set-category tag=7\nfield payload bytes\n  record set-airtightness tag=300\nfield payload bytes\nrecord reset tag=0\nfield payload bytes\n";

#[derive(Clone, Debug, PartialEq, DslOps)]
enum TaggedMutation {
    SetCategory { category: String },
    SetAirtightness { n50: f64 },
    Reset,
}

const SET_CATEGORY: u8 = protocol_record::tag_u8(PROTOCOL, "set-category");

#[semio_framework_async_macros::async_test]
async fn scanner_agrees_with_the_dialect_parser() {
    let parsed = parse_protocol(PROTOCOL).expect("protocol parses");
    let declared: Vec<(String, u64)> = parsed.blocks.iter().filter_map(|block| match block { Block::Record { name, tag: Some(tag), .. } => Some((name.clone(), *tag)), _ => None }).collect();
    let scanned: Vec<(String, u64)> = protocol_record::records(PROTOCOL).map(|(kind, tag)| (kind.to_string(), tag)).collect();
    assert_eq!(scanned, declared);
    assert_eq!(SET_CATEGORY, 7);
    assert_eq!(protocol_record::tag(PROTOCOL, "set-airtightness"), 300);
    assert_eq!(protocol_record::kind(PROTOCOL, 0), Some("reset"));
    assert_eq!(protocol_record::kind(PROTOCOL, 9), None);
}

#[semio_framework_async_macros::async_test]
async fn tagged_ops_carry_the_declared_tag_and_round_trip() {
    for (op, tag) in [(TaggedMutation::SetCategory { category: "roof".into() }, vec![7u8]), (TaggedMutation::SetAirtightness { n50: 0.9 }, vec![0xac, 0x02]), (TaggedMutation::Reset, vec![0])] {
        let bytes = variants_binary::encode_tagged_op(PROTOCOL, &op).expect("encodes");
        assert_eq!(bytes[0], variants_binary::OP_BINARY_FORMAT);
        assert_eq!(&bytes[1..1 + tag.len()], tag.as_slice());
        assert_eq!(variants_binary::decode_tagged_op::<TaggedMutation>(PROTOCOL, &bytes).expect("decodes"), op);
    }
    assert!(variants_binary::decode_tagged_op::<TaggedMutation>(PROTOCOL, &[variants_binary::OP_BINARY_FORMAT, 9]).is_err());
}

#[semio_framework_async_macros::async_test]
async fn tagged_text_lines_carry_the_record_tag_instead_of_the_keyword() {
    let bytes = tagged_text_binary::encode_line(PROTOCOL, "set-category name=\"roof\"").expect("encodes");
    assert_eq!(&bytes[..2], &[tagged_text_binary::OP_BINARY_FORMAT, 7]);
    assert_eq!(&bytes[2..], b"name=\"roof\"");
    assert_eq!(tagged_text_binary::decode_line(PROTOCOL, &bytes).expect("decodes"), "set-category name=\"roof\"");
    assert_eq!(tagged_text_binary::decode_line(PROTOCOL, &tagged_text_binary::encode_line(PROTOCOL, "reset").unwrap()).unwrap(), "reset");
    assert!(tagged_text_binary::encode_line(PROTOCOL, "ghost").is_err());
}

//! 📦️ Boxed field ownership preserves the neutral DSL value and operation wire shape.

use super::*;

#[derive(Clone, Debug, PartialEq, DslRecord, serde::Serialize, serde::Deserialize)]
struct BoxedFieldRecord {
    label: String,
    count: u32,
}

#[derive(Clone, Debug, PartialEq, DslOps)]
enum BoxedFieldOperation {
    #[dsl(key = "replace")]
    Replace {
        #[dsl(block)]
        config: Box<BoxedFieldRecord>,
    },
}

#[derive(Clone, Debug, PartialEq, DslOps)]
enum InlineFieldOperation {
    #[dsl(key = "replace")]
    Replace {
        #[dsl(block)]
        config: BoxedFieldRecord,
    },
}

fn boxed_field_vectors() -> serde_json::Value {
    serde_json::from_str(include_str!("../../🧫️fixtures/📦️boxed-fields/🔣️.json")).expect("neutral boxed field vectors")
}

#[test]
fn boxed_dsl_fields_match_neutral_values_and_serde() {
    let vectors = boxed_field_vectors();
    let reference: Box<String> = serde_json::from_value(vectors["text"].clone()).expect("serde boxed string");
    let value = FieldValue::Text(reference.as_ref().clone());
    let restored = <Box<String> as DslField>::from_value(&value).expect("boxed text field");
    assert_eq!(restored, reference);
    assert_eq!(DslField::to_value(&restored), value);
    assert!(matches!(<Box<String> as DslField>::shape(), Shape::Text));
    assert_eq!(<Box<String> as DslField>::from_value(&FieldValue::UInt(7)).unwrap_err(), <String as DslField>::from_value(&FieldValue::UInt(7)).unwrap_err());
    let reference: Box<BoxedFieldRecord> = serde_json::from_value(vectors["record"].clone()).expect("serde boxed record");
    let value = DslField::to_value(reference.as_ref());
    let restored = <Box<BoxedFieldRecord> as DslField>::from_value(&value).expect("boxed record field");
    assert_eq!(DslField::to_value(&restored), value);
    assert_eq!(serde_json::to_value(&restored).expect("serde restored record"), vectors["record"]);
    assert_eq!(restored, reference);
}

#[test]
fn boxed_dsl_operation_matches_unboxed_text_and_binary() {
    let vectors = boxed_field_vectors();
    let config: BoxedFieldRecord = serde_json::from_value(vectors["record"].clone()).expect("serde neutral record");
    let inline = InlineFieldOperation::Replace { config: config.clone() };
    let boxed = BoxedFieldOperation::Replace { config: Box::new(config) };
    let inline_bytes = variants_binary::encode_op(&inline).expect("inline binary");
    let boxed_bytes = variants_binary::encode_op(&boxed).expect("boxed binary");
    assert_eq!(boxed_bytes, inline_bytes);
    assert_eq!(variants_binary::decode_op::<BoxedFieldOperation>(&inline_bytes).expect("boxed binary round trip"), boxed);
    assert_eq!(variants_binary::decode_op::<InlineFieldOperation>(&boxed_bytes).expect("inline binary round trip"), inline);
    let (inline_key, inline_record) = inline.to_named_record();
    let (boxed_key, boxed_record) = boxed.to_named_record();
    assert_eq!(boxed_key, inline_key);
    assert_eq!(boxed_record, inline_record);
    let inline_spec = (InlineFieldOperation::variants()[0].1.ordinary)();
    let boxed_spec = (BoxedFieldOperation::variants()[0].1.ordinary)();
    let inline_text = print(&inline_record, &inline_spec, JoinMode::Inline);
    let boxed_text = print(&boxed_record, &boxed_spec, JoinMode::Inline);
    assert_eq!(boxed_text, inline_text);
    let parsed = parse(&boxed_text, &boxed_spec, &ParseOptions { limits: Limits::default(), mode: SourceMode::Inline }).expect("boxed text parse");
    assert_eq!(BoxedFieldOperation::from_named_record(&boxed_key, &parsed).expect("boxed text round trip"), boxed);
    let BoxedFieldOperation::Replace { config } = boxed;
    assert_eq!(serde_json::to_value(config).expect("serde operation payload"), vectors["record"]);
}

