    let mut next = || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    for _ in 0..2_000 {
        let x = (next() % 2000) as i64 - 1000;
        let y = (next() % 2000) as i64 - 1000;
        let zoom = (next() % 2000) as i64 - 1000;
