        depth.admit_byte(offset as u64, byte).expect("depth admission");
        while depth.pending.is_some() {
            if matches!(depth.grant(), Err(PackError::LimitExceeded(_))) {
                depth_failed = true;
                break;
            }
        }
        if depth_failed {
            break;
        }
    }
    assert!(depth_failed);
    close_retained_value(&mut depth);
}

